window.TXB=window.TXB||{};TXB["svd/1Ch"]={"1:1":"آدم, شيت, أنوش,","1:2":"قينان, مهللئيل, يارد,","1:3":"أخنوخ, متوشالح, لامك,","1:4":"نوح, سام, حام, يافث.","1:5":"بنو يافث: جومر وماجوج وماداي وياوان وتوبال وماشك وتيراس.","1:6":"وبنو جومر: أشكناز وريفاث وتوجرمة.","1:7":"وبنو ياوان: أليشة وترشيشة وكتيم ودودانيم.","1:8":"بنو حام: كوش ومصرايم وفوط وكنعان.","1:9":"وبنو كوش: سبا وحويلة وسبتا ورعما وسبتكا. وبنو رعما: شبا وددان.","1:10":"وكوش ولد نمرود الذي ابتدأ يكون جبارا في الأرض.","1:11":"ومصرايم ولد: لوديم وعناميم ولهابيم ونفتوحيم","1:12":"وفتروسيم وكسلوحيم, الذين خرج منهم فلشتيم وكفتوريم.","1:13":"وكنعان ولد: صيدون بكره, وحثا","1:14":"واليبوسي والأموري والجرجاشي","1:15":"والحوي والعرقي والسيني","1:16":"والأروادي والصماري والحماثي.","1:17":"بنو سام: عيلام وأشور وأرفكشاد ولود وأرام وعوص وحول وجاثر وماشك.","1:18":"وأرفكشاد ولد شالح, وشالح ولد عابر.","1:19":"ولعابر ولد ابنان اسم الواحد فالج, لأن في أيامه قسمت الأرض. واسم أخيه يقطان.","1:20":"ويقطان ولد: ألموداد وشالف وحضرموت ويارح","1:21":"وهدورام وأوزال ودقلة","1:22":"وعيبال وأبيمايل وشبا","1:23":"وأوفير وحويلة ويوباب. كل هؤلاء بنو يقطان.","1:24":"سام, أرفكشاد, شالح,","1:25":"عابر, فالج, رعو,","1:26":"سروج, ناحور, تارح,","1:27":"أبرام, وهو إبراهيم.","1:28":"ابنا إبراهيم: إسحاق وإسماعيل.","1:29":"هذه مواليدهم. بكر إسماعيل: نبايوت, وقيدار وأدبئيل ومبسام","1:30":"ومشماع ودومة ومسا وحدد وتيماء","1:31":"ويطور ونافيش وقدمة. هؤلاء هم بنو إسماعيل.","1:32":"وأما بنو قطورة سرية إبراهيم, فإنها ولدت: زمران ويقشان ومدان ومديان ويشباق وشوحا. وابنا يقشان: شبا وددان.","1:33":"وبنو مديان: عيفة وعفر وحنوك وأبيداع وألدعة. فكل هؤلاء بنو قطورة.","1:34":"وولد إبراهيم إسحاق. وابنا إسحاق: عيسو وإسرائيل.","1:35":"بنو عيسو: أليفاز ورعوئيل ويعوش ويعلام وقورح.","1:36":"بنو أليفاز: تيمان وأومار وصفي وجعثام وقناز وتمناع وعماليق.","1:37":"بنو رعوئيل: نحث وزارح وشمة ومزة.","1:38":"وبنو سعير: لوطان وشوبال وصبعون وعنى وديشون وإيصر وديشان.","1:39":"وابنا لوطان: حوري وهومام. وأخت لوطان تمناع.","1:40":"بنو شوبال: عليان ومناحة وعيبال وشفي وأونام. وابنا صبعون: أية وعنى.","1:41":"ابن عنى ديشون, وبنو ديشون: حمران وأشبان ويثران وكران.","1:42":"بنو إيصر: بلهان وزعوان ويعقان. وابنا ديشان: عوص وأران.","1:43":"هؤلاء هم الملوك الذين ملكوا في أرض أدوم قبلما ملك ملك لبني إسرائيل: بالع بن بعور. واسم مدينته دنهابة.","1:44":"ومات بالع فملك مكانه يوباب بن زارح من بصرة.","1:45":"ومات يوباب فملك مكانه حوشام من أرض التيماني.","1:46":"ومات حوشام فملك مكانه هدد بن بدد الذي كسر مديان في بلاد موآب, واسم مدينته عويت.","1:47":"ومات هدد فملك مكانه سملة من مسريقة.","1:48":"ومات سملة فملك مكانه شاول من رحوبوت النهر.","1:49":"ومات شاول فملك مكانه بعل حانان بن عكبور.","1:50":"ومات بعل حانان فملك مكانه هدد, واسم مدينته فاعي, واسم امرأته مهيطبئيل بنت مطرد بنت ماء ذهب.","1:51":"ومات هدد. فكانت أمراء أدوم: أمير تمناع, أمير علوة, أمير يتيت,","1:52":"أمير أهوليبامة, أمير أيلة, أمير فينون,","1:53":"أمير قناز, أمير تيمان, أمير مبصار,","1:54":"أمير مجديئيل, أمير عيرام. هؤلاء أمراء أدوم.","2:1":"هؤلاء بنو إسرائيل: رأوبين, شمعون, لاوي ويهوذا, يساكر وزبولون,","2:2":"دان, يوسف وبنيامين, نفتالي, جاد وأشير.","2:3":"بنو يهوذا: عير وأونان وشيلة. ولد الثلاثة من بنت شوع الكنعانية. وكان عير بكر يهوذا شريرا في عيني الرب فأماته.","2:4":"وثامار كنته ولدت له فارص وزارح. كل بني يهوذا خمسة.","2:5":"ابنا فارص: حصرون وحامول.","2:6":"وبنو زارح: زمري وأيثان وهيمان وكلكول ودارع. الجميع خمسة.","2:7":"وابن كرمي عخار مكدر إسرائيل الذي خان في الحرام.","2:8":"وابن أيثان: عزريا.","2:9":"وبنو حصرون الذين ولدوا له: يرحمئيل ورام وكلوباي.","2:10":"ورام ولد عميناداب, وعميناداب ولد نحشون رئيس بني يهوذا,","2:11":"ونحشون ولد سلمو, وسلمو ولد بوعز,","2:12":"وبوعز ولد عوبيد, وعوبيد ولد يسى,","2:13":"ويسى ولد: بكره أليآب, وأبيناداب الثاني, وشمعى الثالث,","2:14":"ونثنئيل الرابع, ورداي الخامس,","2:15":"وأوصم السادس, وداود السابع.","2:16":"وأختاهم صروية وأبيجايل. وبنو صروية: أبشاي ويوآب وعسائيل, ثلاثة.","2:17":"وأبيجايل ولدت عماسا, وأبو عماسا يثر الإسماعيلي.","2:18":"وكالب بن حصرون ولد من عزوبة امرأته ومن يريعوث. وهؤلاء بنوها: ياشر وشوباب وأردون.","2:19":"وماتت عزوبة فاتخذ كالب لنفسه أفرات فولدت له حور.","2:20":"وحور ولد أوري, وأوري ولد بصلئيل.","2:21":"وبعد دخل حصرون على بنت ماكير أبي جلعاد واتخذها وهو ابن ستين سنة فولدت له سجوب.","2:22":"وسجوب ولد يائير, وكان له ثلاث وعشرون مدينة في أرض جلعاد.","2:23":"وأخذ جشور وأرام حووث يائير منهم مع قناة وقراها, ستين مدينة. كل هؤلاء بنو ماكير أبي جلعاد.","2:24":"وبعد وفاة حصرون في كالب أفراتة, ولدت له أبياه امرأة حصرون أشحور أبا تقوع.","2:25":"وكان بنو يرحمئيل بكر حصرون: البكر رام, ثم بونة وأورن وأوصم وأخيا.","2:26":"وكانت امرأة أخرى ليرحمئيل اسمها عطارة. هي أم أونام.","2:27":"وكان بنو رام بكر يرحمئيل: معص ويمين وعاقر.","2:28":"وكان ابنا أونام: شماي وياداع. وابنا شماي: ناداب وأبيشور.","2:29":"واسم امرأة أبيشور أبيحايل, وولدت له أحبان وموليد.","2:30":"وابنا ناداب: سلد وأفايم. ومات سلد بلا بنين.","2:31":"وابن أفايم يشعي, وابن يشعي شيشان, وابن شيشان أحلاي.","2:32":"وابنا ياداع أخي شماي: يثر ويوناثان. ومات يثر بلا بنين.","2:33":"وابنا يوناثان: فالت وزازا. هؤلاء هم بنو يرحمئيل.","2:34":"ولم يكن لشيشان بنون بل بنات. وكان لشيشان عبد مصري اسمه يرحع,","2:35":"فأعطى شيشان ابنته ليرحع عبده امرأة, فولدت له عتاي.","2:36":"وعتاي ولد ناثان, وناثان ولد زاباد,","2:37":"وزاباد ولد أفلال, وأفلال ولد عوبيد,","2:38":"وعوبيد ولد ياهو, وياهو ولد عزريا,","2:39":"وعزريا ولد حالص, وحالص ولد إلعاسة,","2:40":"وإلعاسة ولد سسماي, وسسماي ولد شلوم,","2:41":"وشلوم ولد يقمية, ويقمية ولد أليشمع.","2:42":"وبنو كالب أخي يرحمئيل: ميشاع بكره. هو أبو زيف. وبنو مريشة أبي حبرون.","2:43":"وبنو حبرون: قورح وتفوح وراقم وشامع.","2:44":"وشامع ولد راقم أبا يرقعام. وراقم ولد شماي.","2:45":"وابن شماي معون, ومعون أبو بيت صور.","2:46":"وعيفة سرية كالب ولدت: حاران وموصا وجازيز. وحاران ولد جازيز.","2:47":"وبنو يهداي: رجم ويوثام وجيشان وفلط وعيفة وشاعف.","2:48":"وأما معكة سرية كالب فولدت: شبر وترحنة.","2:49":"وولدت شاعف أبا مدمنة, وشوا أبا مكبينا وأبا جبعا. وبنت كالب عكسة.","2:50":"هؤلاء هم بنو كالب بن حور بكر أفراتة. شوبال أبو قرية يعاريم","2:51":"وسلما أبو بيت لحم, وحاريف أبو بيت جادير.","2:52":"وكان لشوبال أبي قرية يعاريم بنون: هرواه وحصي همنوحوت.","2:53":"وعشائر قرية يعاريم: اليثري والفوتي والشماتي والمشراعي. من هؤلاء خرج الصرعي والأشتأولي.","2:54":"بنو سلما: بيت لحم والنطوفاتي وعطروت بيت يوآب وحصي المنوحي الصرعي.","2:55":"وعشائر الكتبة سكان يعبيص: ترعاتيم وشمعاتيم وسوكاتيم. هم القينيون الخارجون من حمة أبي بيت ركاب.","3:1":"وهؤلاء هم بنو داود الذين ولدوا له في حبرون: البكر أمنون من أخينوعم اليزرعيلية. الثاني دانيئيل من أبيجايل الكرملية.","3:2":"الثالث أبشالوم ابن معكة بنت تلماي ملك جشور. الرابع أدونيا ابن حجيث.","3:3":"الخامس شفطيا من أبيطال. السادس يثرعام من عجلة امرأته.","3:4":"ولد له ستة في حبرون. وملك هناك سبع سنين وستة أشهر, ثم ملك ثلاثا وثلاثين سنة في أورشليم.","3:5":"وهؤلاء ولدوا له في أورشليم: شمعى وشوباب وناثان وسليمان. أربعة من بثشوع بنت عميئيل.","3:6":"ويبحار وأليشامع وأليفالط","3:7":"ونوجه ونافج ويافيع","3:8":"وأليشمع وألياداع وأليفلط. تسعة.","3:9":"الكل بنو داود ما عدا بني السراري. وثامار هي أختهم.","3:10":"وابن سليمان رحبعام, وابنه أبيا, وابنه آسا, وابنه يهوشافاط,","3:11":"وابنه يورام, وابنه أخزيا, وابنه يوآش,","3:12":"وابنه أمصيا, وابنه عزريا, وابنه يوثام,","3:13":"وابنه آحاز, وابنه حزقيا, وابنه منسى,","3:14":"وابنه آمون, وابنه يوشيا.","3:15":"وبنو يوشيا: البكر يوحانان, الثاني يهوياقيم, الثالث صدقيا, الرابع شلوم.","3:16":"وابنا يهوياقيم: يكنيا ابنه وصدقيا ابنه.","3:17":"وابنا يكنيا: أسير وشألتئيل ابنه","3:18":"وملكيرام وفدايا وشنأصر ويقميا وهوشاماع وندبيا.","3:19":"وابنا فدايا: زربابل وشمعي. وبنو زربابل: مشلام وحننيا وشلومية أختهم,","3:20":"وحشوبة وأوهل وبرخيا وحسديا ويوشب حسد. خمسة.","3:21":"وبنو حننيا: فلطيا ويشعيا, وبنو رفايا, وبنو أرنان, وبنو عوبديا, وبنو شكنيا.","3:22":"وبنو شكنيا: شمعيا وبنو شمعيا: حطوش ويجآل وباريح ونعريا وشافاط. ستة.","3:23":"وبنو نعريا: اليوعيني وحزقيا وعزريقام. ثلاثة.","3:24":"وبنو اليوعيني: هوداياهو وألياشيب وفلايا وعقوب ويوحانان ودلايا وعناني. سبعة.","4:1":"بنو يهوذا: فارص وحصرون وكرمي وحور وشوبال.","4:2":"ورآيا بن شوبال ولد يحث, ويحث ولد أخوماي ولاهد. هذه عشائر الصرعيين.","4:3":"وهؤلاء لأبي عيطم: يزرعيل ويشما ويدباش, واسم أختهم هصللفوني.","4:4":"وفنوئيل أبو جدور, وعازر أبو حوشة. هؤلاء بنو حور بكر أفراتة أبي بيت لحم.","4:5":"وكان لأشحور أبي تقوع امرأتان: حلاة ونعرة.","4:6":"وولدت له نعرة: أخزام وحافر والتيماني والأخشتاري. هؤلاء بنو نعرة.","4:7":"وبنو حلاة: صرث وصوحر وأثنان.","4:8":"وقوص ولد: عانوب وهصوبيبة وعشائر أخرحيل بن هارم.","4:9":"وكان يعبيص أشرف من إخوته. وسمته أمه يعبيص قائلة: «لأني ولدته بحزن».","4:10":"ودعا يعبيص إله إسرائيل قائلا: «ليتك تباركني, وتوسع تخومي, وتكون يدك معي, وتحفظني من الشر حتى لا يتعبني». فآتاه الله بما سأل.","4:11":"وكلوب أخو شوحة ولد محير. هو أبو أشتون.","4:12":"وأشتون ولد بيت رافا وفاسح وتحنة أبا مدينة ناحاش. هؤلاء أهل ريكة.","4:13":"وابنا قناز: عثنيئيل وسرايا, وابن عثنيئيل حثاث.","4:14":"ومعونوثاي ولد عفرة, وسرايا ولد يوآب أبا وادي الصناع, لأنهم كانوا صناعا.","4:15":"وبنو كالب بن يفنة: عيرو وأيلة وناعم. وابن أيلة قناز.","4:16":"وبنو يهللئيل: زيف وزيفة وتيريا وأسرئيل.","4:17":"وبنو عزرة: يثر ومرد وعافر ويالون. وحبلت بمريم وشماي ويشبح أبي أشتموع.","4:18":"وامرأته اليهودية ولدت يارد أبا جدور, وحابر أبا سوكو, ويقوثيئيل أبا زانوح. وهؤلاء بنو بثية بنت فرعون التي أخذها مرد.","4:19":"وبنو امرأته اليهودية أخت نحم: أبي قعيلة الجرمي وأشتموع المعكي.","4:20":"وبنو شيمون: أمنون ورنة بن حانان, وتيلون. وابنا يشعي: زوحيت وبنزوحيت.","4:21":"بنو شيلة بن يهوذا: عير أبو ليكة, ولعدة أبو مريشة, وعشائر بيت عاملي البز من بيت أشبيع,","4:22":"ويوقيم, وأهل كزيبا, ويوآش وساراف, الذين هم أصحاب موآب ويشوبي لحم. وهذه الأمور قديمة.","4:23":"هؤلاء هم الخزافون وسكان نتاعيم وجديرة. أقاموا هناك مع الملك لشغله.","4:24":"بنو شمعون: نموئيل ويامين ويريب وزارح وشاول,","4:25":"وابنه شلوم وابنه مبسام وابنه مشماع.","4:26":"وبنو مشماع: حموئيل ابنه, زكور ابنه, شمعي ابنه.","4:27":"وكان لشمعي ستة عشر ابنا وست بنات. وأما إخوته فلم يكن لهم بنون كثيرون, وكل عشائرهم لم يكثروا مثل بني يهوذا.","4:28":"وأقاموا في بئر سبع ومولادة وحصر شوعال","4:29":"وفي بلهة وعاصم وتولاد","4:30":"وفي بتوئيل وحرمة وصقلغ","4:31":"وفي بيت مركبوت وحصر سوسيم وبيت برئي وشعرايم. هذه مدنهم إلى حينما ملك داود.","4:32":"وقراهم: عيطم وعين ورمون وتوكن وعاشان, خمس مدن.","4:33":"وجميع قراهم التي حول هذه المدن إلى بعل. هذه مساكنهم وأنسابهم.","4:34":"ومشوباب ويمليك ويوشا بن أمصيا,","4:35":"ويوئيل وياهو بن يوشبيا بن سرايا بن عسيئيل,","4:36":"وأليوعيناي ويعقوبا ويشوحايا وعسايا وعديئيل ويسيميئيل وبنايا","4:37":"وزيزا بن شفعي بن ألون بن يدايا بن شمري بن شمعيا.","4:38":"هؤلاء الواردون بأسمائهم رؤساء في عشائرهم وبيوت آبائهم امتدوا كثيرا,","4:39":"وساروا إلى مدخل جدور إلى شرقي الوادي ليفتشوا على مرعى لماشيتهم.","4:40":"فوجدوا مرعى خصبا وجيدا, وكانت الأرض واسعة الأطراف مستريحة ومطمئنة, لأن آل حام سكنوا هناك في القديم.","4:41":"وجاء هؤلاء المكتوبة أسماؤهم في أيام حزقيا ملك يهوذا. وضربوا خيمهم والمعونيين الذين وجدوا هناك وحرموهم إلى هذا اليوم, وسكنوا مكانهم لأن هناك مرعى لماشيتهم.","4:42":"ومنهم, من بني شمعون, ذهب إلى جبل سعير خمس مئة رجل, وقدامهم فلطيا ونعريا ورفايا وعزيئيل بنو يشعي.","4:43":"وضربوا بقية المنفلتين من عماليق, وسكنوا هناك إلى هذا اليوم.","5:1":"وبنو رأوبين بكر إسرائيل. لأنه هو البكر, ولأجل تدنيسه فراش أبيه, أعطيت بكوريته لبني يوسف بن إسرائيل, فلم ينسب بكرا.","5:2":"لأن يهوذا اعتز على إخوته ومنه الرئيس, وأما البكورية فليوسف.","5:3":"بنو رأوبين بكر إسرائيل: حنوك وفلو وحصرون وكرمي.","5:4":"بنو يوئيل: ابنه شمعيا, وابنه جوج, وابنه شمعي,","5:5":"وابنه ميخا, وابنه رآيا, وابنه بعل,","5:6":"وابنه بئيرة الذي سباه تغلث فلناسر ملك أشور. هو رئيس الرأوبينيين.","5:7":"وإخوته حسب عشائرهم في الانتساب حسب مواليدهم: الرئيس يعيئيل وزكريا,","5:8":"وبالع بن عزاز بن شامع بن يوئيل الذي سكن في عروعير حتى إلى نبو وبعل معون.","5:9":"وسكن شرقا إلى مدخل البرية من نهر الفرات, لأن ماشيتهم كثرت في أرض جلعاد.","5:10":"وفي أيام شاول عملوا حربا مع الهاجريين فسقطوا بأيديهم وسكنوا في خيامهم في جميع جهات شرق جلعاد.","5:11":"وبنو جاد سكنوا مقابلهم في أرض باشان حتى إلى سلخة.","5:12":"يوئيل الرأس, وشافاط ثانيه, ويعناي وشافاط في باشان.","5:13":"وإخوتهم حسب بيوت آبائهم: ميخائيل ومشلام وشبع ويوراي ويعكان وزيع وعابر. سبعة.","5:14":"هؤلاء بنو أبيحايل بن حوري بن ياروح بن جلعاد بن ميخائيل بن يشيشاي بن يحدو بن بوز.","5:15":"وأخي بن عبدئيل بن جوني رئيس بيت آبائهم.","5:16":"وسكنوا في جلعاد في باشان وقراها, وفي جميع مسارح شارون عند مخارجها.","5:17":"جميعهم انتسبوا في أيام يوثام ملك يهوذا, وفي أيام يربعام ملك إسرائيل.","5:18":"بنو رأوبين والجاديون ونصف سبط منسى من بني البأس, رجال يحملون الترس والسيف ويشدون القوس ومتعلمون القتال, أربعة وأربعون ألفا وسبع مئة وستون من الخارجين في الجيش.","5:19":"وعملوا حربا مع الهاجريين ويطور ونافيش ونوداب,","5:20":"فانتصروا عليهم. فدفع ليدهم الهاجريون وكل من معهم لأنهم صرخوا إلى الله في القتال, فاستجاب لهم لأنهم اتكلوا عليه.","5:21":"ونهبوا ماشيتهم: جمالهم خمسين ألفا, وغنما مئتين وخمسين ألفا, وحميرا ألفين. وسبوا أناسا مئة ألف.","5:22":"لأنه سقط قتلى كثيرون, لأن القتال إنما كان من الله. وسكنوا مكانهم إلى السبي.","5:23":"وبنو نصف سبط منسى سكنوا في الأرض وامتدوا من باشان إلى بعل حرمون وسنير وجبل حرمون.","5:24":"وهؤلاء رؤوس بيوت آبائهم: عافر ويشعي وأليئيل وعزريئيل ويرميا وهودويا ويحديئيل,, رجال جبابرة بأس وذوو اسم ورؤوس لبيوت آبائهم.","5:25":"وخانوا إله آبائهم وزنوا وراء آلهة شعوب الأرض الذين طردهم الرب من أمامهم.","5:26":"فنبه إله إسرائيل روح فول ملك أشور وروح تغلث فلناسر ملك أشور, فسباهم, الرأوبينيين والجاديين ونصف سبط منسى, وأتى بهم إلى حلح وخابور وهارا ونهر جوزان إلى هذا اليوم.","6:1":"بنو لاوي: جرشون وقهات ومراري.","6:2":"وبنو قهات: عمرام ويصهار وحبرون وعزيئيل.","6:3":"وبنو عمرام: هارون وموسى ومريم. وبنو هارون: ناداب وأبيهو وأليعازار وإيثامار.","6:4":"ألعازار ولد فينحاس, وفينحاس ولد أبيشوع,","6:5":"وأبيشوع ولد بقي, وبقي ولد عزي,","6:6":"وعزي ولد زرحيا, وزرحيا ولد مرايوث,","6:7":"ومرايوث ولد أمريا, وأمريا ولد أخيطوب,","6:8":"وأخيطوب ولد صادوق, وصادوق ولد أخيمعص,","6:9":"وأخيمعص ولد عزريا, وعزريا ولد يوحانان,","6:10":"ويوحانان ولد عزريا, وهو الذي كهن في البيت الذي بناه سليمان في أورشليم,","6:11":"وعزريا ولد أمريا, وأمريا ولد أخيطوب,","6:12":"وأخيطوب ولد صادوق, وصادوق ولد شلوم,","6:13":"وشلوم ولد حلقيا, وحلقيا ولد عزريا,","6:14":"وعزريا ولد سرايا, وسرايا ولد يهوصاداق,","6:15":"ويهوصاداق سار في سبي الرب يهوذا وأورشليم بيد نبوخذناصر.","6:16":"بنو لاوي: جرشوم وقهات ومراري.","6:17":"وهذان اسما ابني جرشوم: لبني وشمعي.","6:18":"وبنو قهات: عمرام ويصهار وحبرون وعزيئيل.","6:19":"وابنا مراري: محلي وموشي. فهذه عشائر اللاويين حسب آبائهم.","6:20":"لجرشوم: لبني ابنه, ويحث ابنه, وزمة ابنه,","6:21":"ويوآخ ابنه, وعدو ابنه, وزارح ابنه, ويأثراي ابنه.","6:22":"بنو قهات: عميناداب ابنه, وقورح ابنه, وأسير ابنه,","6:23":"وألقانة ابنه, وأبيأساف ابنه, وأسير ابنه,","6:24":"وتحث ابنه, وأوريئيل ابنه, وعزيا ابنه, وشاول ابنه.","6:25":"وابنا ألقانة: عماساي وأخيموت,","6:26":"وألقانة. بنو ألقانة: صوفاي ابنه, ونحث ابنه,","6:27":"وأليآب ابنه, ويروحام ابنه, وألقانة ابنه.","6:28":"وابنا صموئيل: البكر وشني ثم أبيا.","6:29":"بنو مراري: محلي, ولبني ابنه, وشمعي ابنه, وعزة ابنه,","6:30":"وشمعى ابنه, وحجيا ابنه, وعسايا ابنه.","6:31":"وهؤلاء هم الذين أقامهم داود على الغناء في بيت الرب بعدما استقر التابوت.","6:32":"وكانوا يخدمون أمام مسكن خيمة الاجتماع بالغناء إلى أن بنى سليمان بيت الرب في أورشليم, فقاموا على خدمتهم حسب ترتيبهم.","6:33":"وهؤلاء هم القائمون مع بنيهم. من بني القهاتيين: هيمان المغني ابن يوئيل بن صموئيل","6:34":"بن ألقانة بن يروحام بن إيليئيل بن توح","6:35":"بن صوف بن ألقانة بن محث بن عماساي","6:36":"بن ألقانة بن يوئيل بن عزريا بن صفنيا","6:37":"بن تحث بن أسير بن أبياساف بن قورح","6:38":"بن يصهار بن قهات بن لاوي بن إسرائيل.","6:39":"وأخوه آساف الواقف عن يمينه. آساف بن برخيا بن شمعي","6:40":"بن ميخائيل بن بعسيا بن ملكيا","6:41":"بن أثناي بن زارح بن عدايا","6:42":"بن أيثان بن زمة بن شمعي","6:43":"بن يحث بن جرشوم بن لاوي.","6:44":"وبنو مراري إخوتهم عن اليسار. أيثان بن قيشي بن عبدي بن ملوخ","6:45":"بن حشبيا بن أمصيا بن حلقيا","6:46":"بن أمصي بن باني بن شامر","6:47":"بن محلي بن موشي بن مراري بن لاوي.","6:48":"وإخوتهم اللاويون مقامون لكل خدمة مسكن بيت الله.","6:49":"وأما هارون وبنوه فكانوا يوقدون على مذبح المحرقة وعلى مذبح البخور مع كل عمل قدس الأقداس, وللتكفير عن إسرائيل حسب كل ما أمر به موسى عبد الله.","6:50":"وهؤلاء بنو هارون: ألعازار ابنه, وفينحاس ابنه, وأبيشوع ابنه,","6:51":"وبقي ابنه, وعزي ابنه, وزرحيا ابنه,","6:52":"ومرايوث ابنه, وأمريا ابنه, وأخيطوب ابنه,","6:53":"وصادوق ابنه, وأخيمعص ابنه.","6:54":"وهذه مساكنهم مع ضياعهم وتخومهم: لبني هارون, لعشيرة القهاتيين لأنه لهم كانت القرعة.","6:55":"وأعطوهم حبرون في أرض يهوذا ومسارحها حواليها.","6:56":"وأما حقل المدينة وديارها فأعطوها لكالب بن يفنة.","6:57":"وأعطوا لبني هارون مدن الملجإ حبرون ولبنة ومسارحها, ويتير وأشتموع ومسارحها","6:58":"وحيلين ومسارحها, ودبير ومسارحها,","6:59":"وعاشان ومسارحها, وبيت شمس ومسارحها.","6:60":"ومن سبط بنيامين جبع ومسارحها, وعلمث ومسارحها, وعناثوث ومسارحها. جميع مدنهم ثلاث عشرة مدينة حسب عشائرهم.","6:61":"ولبني قهات الباقين من عشيرة السبط من نصف السبط, نصف منسى, بالقرعة عشر مدن.","6:62":"ولبني جرشوم حسب عشائرهم. من سبط يساكر ومن سبط أشير ومن سبط نفتالي ومن سبط منسى في باشان ثلاث عشرة مدينة.","6:63":"لبني مراري حسب عشائرهم من سبط رأوبين ومن سبط جاد ومن سبط زبولون بالقرعة اثنتا عشرة مدينة.","6:64":"فأعطى بنو إسرائيل اللاويين المدن ومسارحها.","6:65":"وأعطوا بالقرعة من سبط يهوذا ومن سبط بني شمعون ومن سبط بني بنيامين هذه المدن التي سموها بأسماء.","6:66":"وبعض عشائر بني قهات كانت مدن تخمهم من سبط أفرايم.","6:67":"وأعطوهم مدن الملجإ: شكيم ومسارحها في جبل أفرايم, وجازر ومسارحها,","6:68":"ويقمعام ومسارحها, وبيت حورون ومسارحها,","6:69":"وأيلون ومسارحها, وجت رمون ومسارحها.","6:70":"ومن نصف سبط منسى: عانير ومسارحها, وبلعام ومسارحها, لعشيرة بني قهات الباقين.","6:71":"لبني جرشوم من نصف سبط منسى: جولان في باشان ومسارحها, وعشتاروت ومسارحه.","6:72":"ومن سبط يساكر: قادش ومسارحها, ودبرة ومسارحها,","6:73":"وراموت ومسارحها, وعانيم ومسارحها.","6:74":"ومن سبط أشير: مشآل ومسارحها, وعبدون ومسارحها,","6:75":"وحقوق ومسارحها, ورحوب ومسارحها.","6:76":"ومن سبط نفتالي: قادش في الجليل ومسارحها, وحمون ومسارحها, وقريتايم ومسارحها.","6:77":"لبني مراري الباقين من سبط زبولون: رمونو ومسارحها, وتابور ومسارحها.","6:78":"وفي عبر أردن أريحا شرقي الأردن, من سبط رأوبين: باصر في البرية ومسارحها, ويهصة ومسارحها,","6:79":"وقديموت ومسارحها, وميفعة ومسارحها.","6:80":"ومن سبط جاد: راموت في جلعاد ومسارحها, ومحنايم ومسارحها,","6:81":"وحشبون ومسارحها, ويعزير ومسارحها.","7:1":"وبنو يساكر: تولاع وفوة وياشوب وشمرون أربعة.","7:2":"وبنو تولاع: عزي ورفايا ويريئيل ويحماي ويبسام وشموئيل رؤوس بيت أبيهم تولاع جبابرة بأس حسب مواليدهم. كان عددهم في أيام داود اثنين وعشرين ألفا وست مئة.","7:3":"وابن عزي يزرحيا. وبنو يزرحيا: ميخائيل وعوبديا ويوئيل ويشيا. خمسة, كلهم رؤوس.","7:4":"ومعهم حسب مواليدهم وبيوت آبائهم جيوش أجناد الحرب ستة وثلاثون ألفا, لأنهم كثروا النساء والبنين.","7:5":"وإخوتهم حسب كل عشائر يساكر جبابرة بأس, سبعة وثمانون ألفا مجمل انتسابهم.","7:6":"لبنيامين: بالع وباكر ويديعئيل. ثلاثة.","7:7":"وبنو بالع: أصبون وعزي وعزيئيل ويريموث وعيري. خمسة. رؤوس بيوت آباء جبابرة بأس, وقد انتسبوا اثنين وعشرين ألفا وأربعة وثلاثين.","7:8":"وبنو باكر: زميرة ويوعاش وأليعزر وأليوعيناي وعمري ويريموث وأبيا وعناثوث وعلامث. كل هؤلاء بنو باكر.","7:9":"وانتسابهم حسب مواليدهم رؤوس بيوت آبائهم جبابرة بأس عشرون ألفا ومئتان.","7:10":"وابن يديعئيل بلهان, وبنو بلهان: يعيش وبنيامين وأهود وكنعنة وزيتان وترشيش وأخيشاحر.","7:11":"كل هؤلاء بنو يديعئيل حسب رؤوس الآباء جبابرة البأس سبعة عشر ألفا ومئتان من الخارجين في الجيش للحرب.","7:12":"وشفيم وحفيم ابنا عير, وحوشيم بن أحير.","7:13":"بنو نفتالي: يحصيئيل وجوني ويصر وشلوم, بنو بلهة.","7:14":"بنو منسى: إشريئيل, الذي ولدته سريته الأرامية. ولدت ماكير أبا جلعاد.","7:15":"وماكير اتخذ امرأة أخت حفيم وشفيم واسمها معكة. واسم ابنه الثاني صلفحاد. وكان لصلفحاد بنات.","7:16":"وولدت معكة امرأة ماكير ابنا ودعت اسمه فرش, واسم أخيه شارش, وابناه أولام وراقم.","7:17":"وابن أولام بدان. هؤلاء بنو جلعاد بن ماكير بن منسى.","7:18":"وأخته همولكة ولدت إيشهود وأبيعزر ومحلة.","7:19":"وكان بنو شميداع: أخيان وشكيم ولقحي وأنيعام.","7:20":"وبنو أفرايم: شوتالح وبرد ابنه, وتحث ابنه, وألعادا ابنه, وتحث ابنه,","7:21":"وزاباد ابنه, وشوتالح ابنه وعزر وألعاد, وقتلهم رجال جت المولودون في الأرض لأنهم نزلوا ليسوقوا ماشيتهم.","7:22":"وناح أفرايم أبوهم أياما كثيرة وأتى إخوته ليعزوه.","7:23":"ودخل على امرأته فحبلت وولدت ابنا, فدعا اسمه بريعة, لأن بلية كانت في بيته.","7:24":"وبنته شيرة. وقد بنت بيت حورون السفلى والعليا وأزين شيرة.","7:25":"ورفح ابنه, ورشف, وتلح ابنه, وتاحن ابنه,","7:26":"ولعدان ابنه, وعميهود ابنه, وأليشمع ابنه,","7:27":"ونون ابنه, ويهوشوع ابنه.","7:28":"وأملاكهم ومساكنهم: بيت إيل وقراها, وشرقا نعران, وغربا جازر وقراها, وشكيم وقراها, إلى غزة وقراها.","7:29":"ولجهة بني منسى بيت شان وقراها, وتعنك وقراها, ومجدو وقراها, ودور وقراها. في هذه سكن بنو يوسف بن إسرائيل.","7:30":"بنو أشير: يمنة ويشوة ويشوي وبريعة وسارح أختهم.","7:31":"وابنا بريعة: حابر وملكيئيل. هو أبو برزاوث.","7:32":"وحابر ولد يفليط وشومير وحوثام وشوعا أختهم.","7:33":"وبنو يفليط: فاسك وبمهال وعشوة. هؤلاء بنو يفليط.","7:34":"وبنو شامر: آخي ورهجة ويحبة وأرام.","7:35":"وبنو هيلام أخيه: صوفح ويمناع وشالش وعامال.","7:36":"وبنو صوفح: سوح وحرنفر وشوعال وبيري ويمرة","7:37":"وباصر وهود وشما وشلشة ويثران وبئيرا.","7:38":"وبنو يثر: يفنة وفسفة وأرا.","7:39":"وبنو علا: آرح وحنيئيل ورصيا.","7:40":"كل هؤلاء بنو أشير رؤوس بيوت آباء منتخبون جبابرة بأس, رؤوس الرؤساء وانتسابهم في الجيش في الحرب, عددهم من الرجال ستة وعشرون ألفا.","8:1":"وبنيامين ولد: بالع بكره, وأشبيل الثاني, وأخرخ الثالث,","8:2":"ونوحة الرابع, ورافا الخامس.","8:3":"وكان بنو بالع: أدار وجيرا وأبيهود","8:4":"وأبيشوع ونعمان وأخوخ","8:5":"وحيرا وشفوفان وحورام.","8:6":"وهؤلاء بنو آحود. هؤلاء رؤوس آباء سكان جبع, ونقلوهم إلى مناحة,","8:7":"أي: نعمان وأخيا. وجيرا هو نقلهم, وولد: عزا وأخيحود.","8:8":"وشحرايم ولد في بلاد موآب بعد إطلاقه امرأتيه حوشيم وبعرا.","8:9":"وولد من خودش امرأته: يوباب وظبيا وميشا وملكام","8:10":"ويعوص وشبيا ومرمة. هؤلاء بنو رؤوس آباء.","8:11":"ومن حوشيم ولد: أبيطوب وألفعل.","8:12":"وبنو ألفعل: عابر ومشعام وشامر, وهو بنى أونو ولود وقراها.","8:13":"وبريعة وشمع. هما رأسا آباء لسكان أيلون, وهما طردا سكان جت.","8:14":"وأخيو وشاشق ويريموت","8:15":"وزبديا وعراد وعادر","8:16":"وميخائيل ويشفة ويوخا, أبناء بريعة.","8:17":"وزبديا ومشلام وحزقي وحابر","8:18":"ويشمراي ويزلياه ويوباب, أبناء ألفعل.","8:19":"وياقيم وزكري وزبدي","8:20":"وأليعيناي وصلتاي وإيليئيل","8:21":"وعدايا وبرايا وشمرة, أبناء شمعي.","8:22":"ويشفان وعابر وإيليئيل","8:23":"وعبدون وزكري وحانان","8:24":"وحننيا وعيلام وعنثوثيا","8:25":"ويفديا وفنوئيل, أبناء شاشق.","8:26":"وشمشراي وشحريا وعثليا","8:27":"ويعرشيا وإيليا وزكري, أبناء يروحام.","8:28":"هؤلاء رؤوس آباء. حسب مواليدهم رؤوس. هؤلاء سكنوا في أورشليم.","8:29":"وفي جبعون سكن أبو جبعون, واسم امرأته معكة.","8:30":"وابنه البكر عبدون, ثم صور وقيس وبعل وناداب,","8:31":"وجدور وأخيو وزاكر.","8:32":"ومقلوث ولد شماة. وهم أيضا مع إخوتهم سكنوا في أورشليم مقابل إخوتهم.","8:33":"ونير ولد قيس, وقيس ولد شاول, وشاول ولد يوناثان وملكيشوع وأبيناداب وإشبعل.","8:34":"وابن يهوناثان مريببعل, ومريببعل ولد ميخا.","8:35":"وبنو ميخا: فيثون ومالك وتاريع وآحاز.","8:36":"وآحاز ولد يهوعدة, ويهوعدة ولد علمث وعزموت وزمري. وزمري ولد موصا,","8:37":"وموصا ولد بنعة, ورافة ابنه, وألعاسة ابنه, وآصيل ابنه.","8:38":"ولآصيل ستة بنين وهذه أسماؤهم: عزريقام وبكرو وإسماعيل وشعريا وعوبديا وحانان. كل هؤلاء بنو آصيل.","8:39":"وبنو عاشق أخيه: أولام بكره, ويعوش الثاني, وأليفلط الثالث.","8:40":"وكان بنو أولام رجالا جبابرة بأس يغرقون في القسي, كثيري البنين وبني البنين مئة وخمسين. كل هؤلاء من بني بنيامين.","9:1":"وانتسب كل إسرائيل, وها هم مكتوبون في سفر ملوك إسرائيل. وسبي يهوذا إلى بابل لأجل خيانتهم.","9:2":"والسكان الأولون في ملكهم ومدنهم هم إسرائيل الكهنة واللاويون والنثينيم.","9:3":"وسكن في أورشليم من بني يهوذا, وبني بنيامين, وبني أفرايم ومنسى:","9:4":"عوثاي بن عميهود بن عمري بن إمري بن باني, من بني فارص بن يهوذا.","9:5":"ومن الشيلونيين: عسايا البكر وبنوه.","9:6":"ومن بني زارح: يعوئيل وإخوتهم ست مئة وتسعون.","9:7":"ومن بني بنيامين: سلو بن مشلام بن هودويا بن هسنوأة,","9:8":"ويبنيا بن يروحام, وأيلة بن عزي بن مكري, ومشلام بن شفطيا بن رعوئيل بن يبنيا.","9:9":"وإخوتهم حسب مواليدهم تسع مئة وستة وخمسون. كل هؤلاء الرجال رؤوس آباء لبيوت آبائهم.","9:10":"ومن الكهنة: يدعيا ويهوياريب وياكين,","9:11":"وعزريا بن حلقيا بن مشلام بن صادوق بن مرايوث بن أخيطوب رئيس بيت الله,","9:12":"وعدايا بن يروحام بن فشحور بن ملكيا, ومعساي بن عديئيل بن يحزيرة بن مشلام بن مشليميت بن إمير.","9:13":"وإخوتهم رؤوس بيوت آبائهم ألف وسبع مئة وستون جبابرة بأس لعمل خدمة بيت الله.","9:14":"ومن اللاويين: شمعيا بن حشوب بن عزريقام بن حشبيا من بني مراري.","9:15":"وبقبقر وحرش وجلال ومتنيا بن ميخا بن زكري بن آساف,","9:16":"وعوبديا بن شمعيا بن جلال بن يدوثون, وبرخيا بن آسا بن ألقانة الساكن في قرى النطوفاتيين.","9:17":"والبوابون: شلوم وعقوب وطلمون وأخيمان وإخوتهم. شلوم الرأس.","9:18":"وحتى الآن هم في باب الملك إلى الشرق. هم البوابون لفرق بني لاوي.","9:19":"وشلوم بن قوري بن أبياساف بن قورح وإخوته لبيوت آبائه. القورحيون على عمل الخدمة حراس أبواب الخيمة, وآباؤهم على محلة الرب حراس المدخل.","9:20":"وفينحاس بن ألعازار كان رئيسا عليهم سابقا, والرب معه.","9:21":"وزكريا بن مشلميا كان بواب باب خيمة الاجتماع.","9:22":"جميع هؤلاء المنتخبين بوابين للأبواب مئتان واثنا عشر, وقد انتسبوا حسب قراهم. أقامهم داود وصموئيل الرائي على وظائفهم.","9:23":"وكانوا هم وبنوهم على أبواب بيت الرب بيت الخيمة للحراسة.","9:24":"في الجهات الأربع كان البوابون, في الشرق والغرب والشمال والجنوب.","9:25":"وكان إخوتهم في قراهم للمجيء معهم في السبعة الأيام, حينا بعد حين.","9:26":"لأنه بالوظيفة رؤساء البوابين هؤلاء الأربعة هم لاويون وكانوا على المخادع وعلى خزائن بيت الله.","9:27":"ونزلوا حول بيت الله لأن عليهم الحراسة, وعليهم الفتح كل صباح.","9:28":"وبعضهم على آنية الخدمة, لأنهم كانوا يدخلونها بعدد, ويخرجونها بعدد.","9:29":"وبعضهم اؤتمنوا على الآنية وعلى كل أمتعة القدس وعلى الدقيق والخمر واللبان والأطياب.","9:30":"والبعض من بني الكهنة كانوا يركبون دهون الأطياب.","9:31":"ومتثيا واحد من اللاويين, وهو بكر شلوم القورحي, بالوظيفة على عمل المطبوخات.","9:32":"والبعض من بني القهاتيين من إخوتهم على خبز الوجوه ليهيئوه في كل سبت.","9:33":"فهؤلاء هم المغنون رؤوس آباء اللاويين في المخادع, وهم معفون, لأنه نهارا وليلا عليهم العمل.","9:34":"هؤلاء رؤوس آباء اللاويين. حسب مواليدهم رؤوس. هؤلاء سكنوا في أورشليم.","9:35":"وفي جبعون سكن أبو جبعون يعوئيل, واسم امرأته معكة.","9:36":"وابنه البكر عبدون ثم صور وقيس وبعل ونير وناداب","9:37":"وجدور وأخيو وزكريا ومقلوث.","9:38":"ومقلوث ولد شمآم. وهم أيضا سكنوا مقابل إخوتهم في أورشليم مع إخوتهم.","9:39":"ونير ولد قيس, وقيس ولد شاول, وشاول ولد: يهوناثان وملكيشوع وأبيناداب وإشبعل.","9:40":"وابن يهوناثان مريببعل, ومريببعل ولد ميخا.","9:41":"وبنو ميخا: فيثون ومالك وتحريع وآحاز.","9:42":"وآحاز ولد يعرة, ويعرة ولد علمث وعزموت وزمري. وزمري ولد موصا,","9:43":"وموصا ولد ينعا, ورفايا ابنه, وألعسة ابنه, وآصيل ابنه.","9:44":"وكان لآصيل ستة بنين وهذه أسماؤهم: عزريقام وبكرو ثم إسماعيل وشعريا وعوبديا وحانان. هؤلاء بنو آصيل.","10:1":"وحارب الفلسطينيون إسرائيل, فهرب رجال إسرائيل من أمام الفلسطينيين وسقطوا قتلى في جبل جلبوع.","10:2":"وشد الفلسطينيون وراء شاول ووراء بنيه, وضرب الفلسطينيون يوناثان وأبيناداب وملكيشوع أبناء شاول.","10:3":"واشتدت الحرب على شاول فأصابته رماة القسي, فانجرح من الرماة.","10:4":"فقال شاول لحامل سلاحه: «استل سيفك واطعني به لئلا يأتي هؤلاء الغلف ويقبحوني». فلم يشأ حامل سلاحه لأنه خاف جدا. فأخذ شاول السيف وسقط عليه.","10:5":"فلما رأى حامل سلاحه أنه قد مات شاول, سقط هو أيضا على السيف ومات.","10:6":"فمات شاول وبنوه الثلاثة وكل بيته, ماتوا معا.","10:7":"ولما رأى جميع رجال إسرائيل الذين في الوادي أنهم قد هربوا, وأن شاول وبنيه قد ماتوا, تركوا مدنهم وهربوا, فأتى الفلسطينيون وسكنوا بها.","10:8":"وفي الغد لما جاء الفلسطينيون ليعروا القتلى, وجدوا شاول وبنيه ساقطين في جبل جلبوع,","10:9":"فعروه وأخذوا رأسه وسلاحه, وأرسلوا إلى أرض الفلسطينيين في كل ناحية لأجل تبشير أصنامهم والشعب.","10:10":"ووضعوا سلاحه في بيت آلهتهم, وسمروا رأسه في بيت داجون.","10:11":"ولما سمع كل يابيش جلعاد بكل ما فعل الفلسطينيون بشاول,","10:12":"قام كل ذي بأس وأخذوا جثة شاول وجثث بنيه وجاءوا بها إلى يابيش, ودفنوا عظامهم تحت البطمة في يابيش, وصاموا سبعة أيام.","10:13":"فمات شاول بخيانته التي بها خان الرب من أجل كلام الرب الذي لم يحفظه. وأيضا لأجل طلبه إلى الجان للسؤال,","10:14":"ولم يسأل من الرب, فأماته وحول المملكة إلى داود بن يسى.","11:1":"واجتمع كل رجال إسرائيل إلى داود في حبرون قائلين: «هوذا عظمك ولحمك نحن.","11:2":"ومنذ أمس وما قبله حين كان شاول ملكا كنت أنت تخرج وتدخل إسرائيل, وقد قال لك الرب إلهك: أنت ترعى شعبي إسرائيل وأنت تكون رئيسا لشعبي إسرائيل».","11:3":"وجاء جميع شيوخ إسرائيل إلى الملك إلى حبرون, فقطع داود معهم عهدا في حبرون أمام الرب, ومسحوا داود ملكا على إسرائيل حسب كلام الرب عن يد صموئيل.","11:4":"وذهب داود وكل إسرائيل إلى أورشليم, أي يبوس. وهناك اليبوسيون سكان الأرض.","11:5":"وقال سكان يبوس لداود: «لا تدخل إلى هنا». فأخذ داود حصن صهيون, هي مدينة داود.","11:6":"وقال داود: «إن الذي يضرب اليبوسيين أولا يكون رأسا وقائدا». فصعد أولا يوآب ابن صروية, فصار رأسا.","11:7":"وأقام داود في الحصن, لذلك دعوه «مدينة داود».","11:8":"وبنى المدينة حواليها من القلعة إلى ما حولها. ويوآب جدد سائر المدينة.","11:9":"وكان داود يتزايد متعظما ورب الجنود معه.","11:10":"وهؤلاء رؤساء الأبطال الذين لداود, الذين تشددوا معه في ملكه مع كل إسرائيل لتمليكه حسب كلام الرب من جهة إسرائيل.","11:11":"وهذا هو عدد الأبطال الذين لداود: يشبعام بن حكموني رئيس الثوالث. هو هز رمحه على ثلاث مئة قتلهم دفعة واحدة.","11:12":"وبعده ألعازار بن دودو الأخوخي. هو من الأبطال الثلاثة.","11:13":"هو كان مع داود في فس دميم وقد اجتمع هناك الفلسطينيون للحرب. وكانت قطعة الحقل مملوءة شعيرا, فهرب الشعب من أمام الفلسطينيين.","11:14":"ووقفوا في وسط القطعة وأنقذوها, وضربوا الفلسطينيين. وخلص الرب خلاصا عظيما.","11:15":"ونزل ثلاثة من الثلاثين رئيسا إلى الصخر إلى داود إلى مغارة عدلام وجيش الفلسطينيين نازل في وادي الرفائيين.","11:16":"وكان داود حينئذ في الحصن, وحفظة الفلسطينيين حينئذ في بيت لحم.","11:17":"فتأوه داود وقال: «من يسقيني ماء من بئر بيت لحم التي عند الباب؟»","11:18":"فشق الثلاثة محلة الفلسطينيين واستقوا ماء من بئر بيت لحم التي عند الباب, وحملوه وأتوا به إلى داود, فلم يشأ داود أن يشربه بل سكبه للرب.","11:19":"وقال: «حاشا لي من قبل إلهي أن أفعل ذلك! أأشرب دم هؤلاء الرجال بأنفسهم؟ لأنهم إنما أتوا به بأنفسهم». ولم يشأ أن يشربه. هذا ما فعله الأبطال الثلاثة.","11:20":"وأبشاي أخو يوآب كان رئيس ثلاثة. وهو قد هز رمحه على ثلاث مئة فقتلهم, فكان له اسم بين الثلاثة.","11:21":"من الثلاثة أكرم على الاثنين وكان لهما رئيسا, إلا أنه لم يصل إلى الثلاثة الأول.","11:22":"بنايا بن يهوياداع ابن ذي بأس كثير الأفعال من قبصيئيل. هو الذي ضرب أسدي موآب, وهو الذي نزل وضرب أسدا في وسط جب يوم الثلج.","11:23":"وهو ضرب الرجل المصري الذي قامته خمس أذرع, وفي يد المصري رمح كنول النساجين. فنزل إليه بعصا وخطف الرمح من يد المصري وقتله برمحه.","11:24":"هذا ما فعله بنايا بن يهوياداع, فكان له اسم بين الثلاثة الأبطال.","11:25":"هوذا أكرم على الثلاثين إلا أنه لم يصل إلى الثلاثة. فجعله داود من أصحاب سره.","11:26":"وأبطال الجيش هم: عسائيل أخو يوآب, وألحانان بن دودو من بيت لحم,","11:27":"شموت الهروري, حالص الفلوني,","11:28":"عيرا بن عقيش التقوعي, أبيعزر العناثوثي,","11:29":"سبكاي الحوشاتي, عيلاي الأخوخي,","11:30":"مهراي النطوفاتي, خالد بن بعنة النطوفاتي,","11:31":"إتاي بن ريباي من جبعة بني بنيامين, بنايا الفرعتوني,","11:32":"حوراي من أودية جاعش, أبيئيل العرباتي,","11:33":"عزموت البحرومي, إليحبا الشعلبوني,","11:34":"بنو هاشم الجزوني, يوناثان بن شاجاي الهراري,","11:35":"أخيآم بن ساكار الهراري, أليفال بن أور,","11:36":"حافر المكيراتي, وأخيا الفلوني,","11:37":"حصرو الكرملي, نعراي بن أزباي,","11:38":"يوئيل أخو ناثان, مبحار بن هجري,","11:39":"صالق العموني, نحراي البئيروتي, حامل سلاح يوآب ابن صروية,","11:40":"عيرا اليثري, جارب اليثري,","11:41":"أوريا الحثي, زاباد بن أحلاي,","11:42":"عدينا بن شيزا الرأوبيني, رأس الرأوبينيين ومعه ثلاثون,","11:43":"حانان ابن معكة, يوشافاط المثني,","11:44":"عزيا العشتروتي, شاماع ويعوئيل ابنا حوثام العروعيري,","11:45":"يديعئيل بن شمري, ويوحا أخوه التيصي,","11:46":"إيليئيل من محويم, ويريباي ويوشويا ابنا ألنعم, ويثمة الموآبي,","11:47":"إيليئيل وعوبيد ويعسيئيل من مصوبايا.","12:1":"وهؤلاء هم الذين جاءوا إلى داود إلى صقلغ وهو بعد محجوز عن وجه شاول بن قيس, وهم من الأبطال مساعدون في الحرب,","12:2":"نازعون في القسي, يرمون الحجارة والسهام من القسي باليمين واليسار, من إخوة شاول من بنيامين.","12:3":"الرأس أخيعزر ثم يوآش ابنا شماعة الجبعي, ويزوئيل وفالط ابنا عزموت, وبراخة وياهو العناثوثي,","12:4":"ويشمعيا الجبعوني البطل بين الثلاثين وعلى الثلاثين, ويرميا ويحزيئيل ويوحانان ويوزاباد الجديري,","12:5":"وإلعوزاي ويريموث وبعليا وشمريا وشفطيا الحروفي,","12:6":"وألقانة ويشيا وعزريئيل ويوعزر ويشبعام القورحيون,","12:7":"ويوعيلة وزبديا ابنا يروحام من جدور.","12:8":"ومن الجاديين انفصل إلى داود إلى الحصن في البرية جبابرة البأس رجال جيش للحرب, صافو أتراس ورماح, ووجوههم كوجوه الأسود, وهم كالظبي على الجبال في السرعة:","12:9":"عازر الرأس, وعوبديا الثاني, وأليآب الثالث,","12:10":"ومشمنة الرابع, ويرميا الخامس,","12:11":"وعتاي السادس, وإيليئيل السابع,","12:12":"ويوحانان الثامن, وألزاباد التاسع","12:13":"ويرميا العاشر, ومخبناي الحادي عشر.","12:14":"هؤلاء من بني جاد رؤوس الجيش. صغيرهم لمئة, والكبير لألف.","12:15":"هؤلاء هم الذين عبروا الأردن في الشهر الأول وهو ممتلئ إلى جميع شطوطه وهزموا كل أهل الأودية شرقا وغربا.","12:16":"وجاء قوم من بني بنيامين ويهوذا إلى الحصن إلى داود.","12:17":"فخرج داود لاستقبالهم وأجاب وقال لهم: «إن كنتم قد جئتم بسلام إلي لتساعدوني, يكون لي معكم قلب واحد. وإن كان لكي تدفعوني لعدوي ولا ظلم في يدي, فلينظر إله آبائنا وينصف».","12:18":"فحل الروح على عماساي رأس الثوالث فقال: «لك نحن يا داود, ومعك نحن يا ابن يسى. سلام سلام لك, وسلام لمساعديك. لأن إلهك معينك». فقبلهم داود وجعلهم رؤوس الجيوش.","12:19":"وسقط إلى داود بعض من منسى حين جاء مع الفلسطينيين ضد شاول للقتال ولم يساعدوهم, لأن أقطاب الفلسطينيين أرسلوه بمشورة قائلين: «إنما برؤوسنا يسقط إلى سيده شاول».","12:20":"حين انطلق إلى صقلغ سقط إليه من منسى عدناح ويوزاباد ويديعئيل وميخائيل ويوزاباد وأليهو وصلتاي رؤوس ألوف منسى.","12:21":"وهم ساعدوا داود على الغزاة لأنهم جميعا جبابرة بأس, وكانوا رؤساء في الجيش.","12:22":"لأنه وقتئذ أتى أناس إلى داود يوما فيوما لمساعدته حتى صاروا جيشا عظيما كجيش الله.","12:23":"وهذا عدد رؤوس المتجردين للقتال الذين جاءوا إلى داود إلى حبرون ليحولوا مملكة شاول إليه حسب قول الرب.","12:24":"بنو يهوذا حاملو الأتراس والرماح ستة آلاف وثمان مئة متجرد للقتال.","12:25":"من بني شمعون جبابرة بأس في الحرب سبعة آلاف ومئة.","12:26":"من بني لاوي أربعة آلاف وست مئة.","12:27":"ويهوياداع رئيس الهرونيين ومعه ثلاثة آلاف وسبع مئة.","12:28":"وصادوق غلام جبار بأس وبيت أبيه اثنان وعشرون قائدا.","12:29":"ومن بني بنيامين إخوة شاول ثلاثة آلاف, وإلى هنا كان أكثرهم يحرسون حراسة بيت شاول.","12:30":"ومن بني أفرايم عشرون ألفا وثمان مئة, جبابرة بأس وذوو اسم في بيوت آبائهم.","12:31":"ومن نصف سبط منسى ثمانية عشر ألفا قد تعينوا بأسمائهم لكي يأتوا ويملكوا داود.","12:32":"ومن بني يساكر الخبيرين بالأوقات لمعرفة ما يعمل إسرائيل, رؤوسهم مئتان, وكل إخوتهم تحت أمرهم.","12:33":"من زبولون الخارجون للقتال المصطفون للحرب بجميع أدوات الحرب خمسون ألفا, وللاصطفاف من دون خلاف.","12:34":"ومن نفتالي ألف رئيس ومعهم سبعة وثلاثون ألفا بالأتراس والرماح.","12:35":"ومن الدانيين مصطفون للحرب ثمانية وعشرون ألفا وست مئة.","12:36":"ومن أشير الخارجون للجيش لأجل الاصطفاف للحرب أربعون ألفا.","12:37":"ومن عبر الأردن من الرأوبينيين والجاديين ونصف سبط منسى بجميع أدوات جيش الحرب مئة وعشرون ألفا.","12:38":"كل هؤلاء رجال حرب يصطفون صفوفا, أتوا بقلب تام إلى حبرون ليملكوا داود على كل إسرائيل. وكذلك كل بقية إسرائيل بقلب واحد لتمليك داود.","12:39":"وكانوا هناك مع داود ثلاثة أيام يأكلون ويشربون لأن إخوتهم أعدوا لهم.","12:40":"وكذلك القريبون منهم حتى يساكر وزبولون ونفتالي, كانوا يأتون بخبز على الحمير والجمال والبغال والبقر, وبطعام من دقيق وتين وزبيب وخمر وزيت وبقر وغنم بكثرة, لأنه كان فرح في إسرائيل.","13:1":"وشاور داود قواد الألوف والمئات وكل رئيس.","13:2":"وقال داود لكل جماعة إسرائيل: «إن حسن عندكم وكان ذلك من الرب إلهنا, فلنرسل إلى كل جهة, إلى إخوتنا الباقين في كل أراضي إسرائيل ومعهم الكهنة واللاويون في مدن مسارحهم ليجتمعوا إلينا,","13:3":"فنرجع تابوت إلهنا إلينا لأننا لم نسأل به في أيام شاول».","13:4":"فقال كل الجماعة بأن يفعلوا ذلك, لأن الأمر حسن في أعين جميع الشعب.","13:5":"وجمع داود كل إسرائيل من شيحور مصر إلى مدخل حماة ليأتوا بتابوت الله من قرية يعاريم.","13:6":"وصعد داود وكل إسرائيل إلى بعلة, إلى قرية يعاريم التي ليهوذا, ليصعدوا من هناك تابوت الله الرب الجالس على الكروبيم الذي دعي بالاسم.","13:7":"وأركبوا تابوت الله على عجلة جديدة من بيت أبيناداب, وكان عزا وأخيو يسوقان العجلة,","13:8":"وداود وكل إسرائيل يلعبون أمام الله بكل عز وبأغاني وعيدان ورباب ودفوف وصنوج وأبواق.","13:9":"ولما انتهوا إلى بيدر كيدون, مد عزا يده ليمسك التابوت, لأن الثيران انشمصت.","13:10":"فحمي غضب الرب على عزا وضربه من أجل أنه مد يده إلى التابوت, فمات هناك أمام الله.","13:11":"فاغتاظ داود لأن الرب اقتحم عزا اقتحاما, وسمى ذلك الموضع «فارص عزا» إلى هذا اليوم.","13:12":"وخاف داود الله في ذلك اليوم قائلا: «كيف آتي بتابوت الله إلي؟».","13:13":"ولم ينقل داود التابوت إليه إلى مدينة داود, بل مال به إلى بيت عوبيد أدوم الجتي.","13:14":"وبقي تابوت الله عند بيت عوبيد أدوم في بيته ثلاثة أشهر. وبارك الرب بيت عوبيد أدوم وكل ما له.","14:1":"وأرسل حيرام ملك صور رسلا إلى داود وخشب أرز وبنائين ونجارين ليبنوا له بيتا.","14:2":"وعلم داود أن الرب قد أثبته ملكا على إسرائيل, لأن مملكته ارتفعت متصاعدة من أجل شعبه إسرائيل.","14:3":"وأخذ داود نساء أيضا في أورشليم, وولد أيضا داود بنين وبنات.","14:4":"وهذه أسماء الأولاد الذين كانوا له في أورشليم: شموع وشوباب وناثان وسليمان","14:5":"ويبحار وأليشوع وألفالط","14:6":"ونوجه ونافج ويافيع","14:7":"وأليشمع وبعلياداع وأليفلط.","14:8":"وسمع الفلسطينيون أن داود قد مسح ملكا على كل إسرائيل, فصعد كل الفلسطينيين ليفتشوا على داود. ولما سمع داود خرج لاستقبالهم.","14:9":"فجاء الفلسطينيون وانتشروا في وادي الرفائيين.","14:10":"فسأل داود من الله قائلا: «أأصعد على الفلسطينيين فتدفعهم ليدي؟» فقال له الرب: «اصعد فأدفعهم ليدك».","14:11":"فصعدوا إلى بعل فراصيم وضربهم داود هناك. وقال داود: «قد اقتحم الله أعدائي بيدي كاقتحام المياه». لذلك دعوا اسم ذلك الموضع «بعل فراصيم».","14:12":"وتركوا هناك آلهتهم, فأمر داود فأحرقت بالنار.","14:13":"ثم عاد الفلسطينيون أيضا وانتشروا في الوادي.","14:14":"فسأل أيضا داود من الله, فقال له الله: «لا تصعد وراءهم, تحول عنهم وهلم عليهم مقابل أشجار البكا.","14:15":"وعندما تسمع صوت خطوات في رؤوس أشجار البكا فاخرج حينئذ للحرب, لأن الله يخرج أمامك لضرب محلة الفلسطينيين».","14:16":"ففعل داود كما أمره الله, وضربوا محلة الفلسطينيين من جبعون إلى جازر.","14:17":"وخرج اسم داود إلى جميع الأراضي, وجعل الرب هيبته على جميع الأمم.","15:1":"وعمل داود لنفسه بيوتا في مدينة داود, وأعد مكانا لتابوت الله ونصب له خيمة.","15:2":"حينئذ قال داود: «ليس لأحد أن يحمل تابوت الله إلا للاويين, لأن الرب إنما اختارهم لحمل تابوت الله ولخدمته إلى الأبد».","15:3":"وجمع داود كل إسرائيل إلى أورشليم لأجل إصعاد تابوت الرب إلى مكانه الذي أعده له.","15:4":"فجمع داود بني هارون واللاويين.","15:5":"من بني قهات: أوريئيل الرئيس, وإخوته مئة وعشرين.","15:6":"من بني مراري: عسايا الرئيس, وإخوته مئتين وعشرين.","15:7":"من بني جرشوم: يوئيل الرئيس, وإخوته مئة وثلاثين.","15:8":"من بني أليصافان: شمعيا الرئيس, وإخوته مئتين.","15:9":"من بني حبرون: إيليئيل الرئيس, وإخوته ثمانين.","15:10":"من بني عزيئيل: عميناداب, الرئيس, وإخوته مئة واثني عشر.","15:11":"ودعا داود صادوق وأبياثار الكاهنين واللاويين: أوريئيل وعسايا ويوئيل وشمعيا وإيليئيل وعميناداب,","15:12":"وقال لهم: «أنتم رؤوس آباء اللاويين, فتقدسوا أنتم وإخوتكم وأصعدوا تابوت الرب إله إسرائيل إلى حيث أعددت له.","15:13":"لأنه إذ لم تكونوا في المرة الأولى, اقتحمنا الرب إلهنا, لأننا لم نسأله حسب المرسوم».","15:14":"فتقدس الكهنة واللاويون ليصعدوا تابوت الرب إله إسرائيل.","15:15":"وحمل بنو اللاويين تابوت الله كما أمر موسى حسب كلام الرب بالعصي على أكتافهم.","15:16":"وأمر داود رؤساء اللاويين أن يوقفوا إخوتهم المغنين بآلات غناء, بعيدان ورباب وصنوج, مسمعين برفع الصوت بفرح.","15:17":"فأوقف اللاويون هيمان بن يوئيل, ومن إخوته آساف بن برخيا, ومن بني مراري إخوتهم إيثان بن قوشيا,","15:18":"ومعهم إخوتهم الثواني: زكريا وبين ويعزئيل وشميراموث ويحيئيل وعني وأليآب وبنايا ومعسيا ومتثيا وأليفليا ومقنيا وعوبيد أدوم ويعيئيل البوابين.","15:19":"والمغنون: هيمان وآساف وإيثان بصنوج نحاس للتسميع.","15:20":"وزكريا وعزيئيل وشميراموث ويحيئيل وعني وألياب ومعسيا وبنايا بالرباب على الجواب.","15:21":"ومتثيا وأليفليا ومقنيا وعوبيد أدوم ويعيئيل وعززيا بالعيدان على القرار للإمامة.","15:22":"وكننيا رئيس اللاويين على الحمل مرشدا في الحمل لأنه كان خبيرا.","15:23":"وبرخيا وألقانة بوابان للتابوت.","15:24":"وشبنيا ويوشافاط ونثنئيل وعماساي وزكريا وبنايا وأليعزر الكهنة ينفخون بالأبواق أمام تابوت الله, وعوبيد أدوم ويحيى بوابان للتابوت.","15:25":"وكان داود وشيوخ إسرائيل ورؤساء الألوف هم الذين ذهبوا لإصعاد تابوت عهد الرب, من بيت عوبيد أدوم بفرح.","15:26":"ولما أعان الله اللاويين حاملي تابوت عهد الرب, ذبحوا سبعة عجول وسبعة كباش.","15:27":"وكان داود لابسا جبة من كتان, وجميع اللاويين حاملين التابوت, والمغنون وكننيا رئيس الحمل مع المغنين. وكان على داود أفود من كتان.","15:28":"فكان جميع إسرائيل يصعدون تابوت عهد الرب بهتاف, وبصوت الأصوار والأبواق والصنوج, يصوتون بالرباب والعيدان.","15:29":"ولما دخل تابوت عهد الرب مدينة داود, أشرفت ميكال بنت شاول من الكوة فرأت الملك داود يرقص ويلعب, فاحتقرته في قلبها.","16:1":"وأدخلوا تابوت الله وأثبتوه في وسط الخيمة التي نصبها له داود, وقربوا محرقات وذبائح سلامة أمام الله.","16:2":"ولما انتهى داود من إصعاد المحرقات وذبائح السلامة بارك الشعب باسم الرب.","16:3":"وقسم على كل آل إسرائيل من الرجال والنساء, على كل إنسان, رغيف خبز وكأس خمر وقرص زبيب.","16:4":"وجعل أمام تابوت الرب من اللاويين خداما, ولأجل التذكير والشكر وتسبيح الرب إله إسرائيل:","16:5":"آساف الرأس وزكريا ثانيه, ويعيئيل وشميراموث ويحيئيل ومتثيا وأليآب وبنايا وعوبيد أدوم ويعيئيل بآلات رباب وعيدان. وكان آساف يصوت بالصنوج.","16:6":"وبنايا ويحزيئيل الكاهنان بالأبواق دائما أمام تابوت عهد الله.","16:7":"حينئذ في ذلك اليوم أولا جعل داود يحمد الرب بيد آساف وإخوته:","16:8":"«احمدوا الرب. ادعوا باسمه. أخبروا في الشعوب بأعماله.","16:9":"غنوا له. ترنموا له. تحادثوا بكل عجائبه.","16:10":"افتخروا باسم قدسه. تفرح قلوب الذين يلتمسون الرب.","16:11":"اطلبوا الرب وعزه. التمسوا وجهه دائما.","16:12":"اذكروا عجائبه التي صنع. آياته وأحكام فمه.","16:13":"يا ذرية إسرائيل عبده, وبني يعقوب مختاريه.","16:14":"هو الرب إلهنا. في كل الأرض أحكامه.","16:15":"اذكروا إلى الأبد عهده, الكلمة التي أوصى بها إلى ألف جيل.","16:16":"الذي قطعه مع إبراهيم. وقسمه لإسحاق.","16:17":"وقد أقامه ليعقوب فريضة, ولإسرائيل عهدا أبديا.","16:18":"قائلا: لك أعطي أرض كنعان حبل ميراثكم.","16:19":"حين كنتم عددا قليلا, قليلين جدا وغرباء فيها.","16:20":"وذهبوا من أمة إلى أمة ومن مملكة إلى شعب آخر.","16:21":"لم يدع أحدا يظلمهم بل وبخ من أجلهم ملوكا.","16:22":"لا تمسوا مسحائي ولا تؤذوا أنبيائي.","16:23":"«غنوا للرب يا كل الأرض. بشروا من يوم إلى يوم بخلاصه.","16:24":"حدثوا في الأمم بمجده وفي كل الشعوب بعجائبه.","16:25":"لأن الرب عظيم ومفتخر جدا. وهو مرهوب فوق جميع الآلهة.","16:26":"لأن كل آلهة الأمم أصنام, وأما الرب فقد صنع السماوات.","16:27":"الجلال والبهاء أمامه. العزة والبهجة في مكانه.","16:28":"هبوا الرب يا عشائر الشعوب, هبوا الرب مجدا وعزة.","16:29":"هبوا الرب مجد اسمه. احملوا هدايا وتعالوا إلى أمامه. اسجدوا للرب في زينة مقدسة.","16:30":"ارتعدوا أمامه يا جميع الأرض. تثبتت المسكونة أيضا. لا تتزعزع.","16:31":"لتفرح السماوات وتبتهج الأرض ويقولوا في الأمم: الرب قد ملك.","16:32":"ليعج البحر وملؤه, ولتبتهج البرية وكل ما فيها.","16:33":"حينئذ تترنم أشجار الوعر أمام الرب لأنه جاء ليدين الأرض.","16:34":"احمدوا الرب لأنه صالح, لأن إلى الأبد رحمته.","16:35":"وقولوا: خلصنا يا إله خلاصنا, واجمعنا وأنقذنا من الأمم لنحمد اسم قدسك, ونتفاخر بتسبيحتك.","16:36":"مبارك الرب إله إسرائيل من الأزل وإلى الأبد». فقال كل الشعب: «آمين» وسبحوا الرب.","16:37":"وترك هناك أمام تابوت عهد الرب آساف وإخوته ليخدموا أمام التابوت دائما خدمة كل يوم بيومها,","16:38":"وعوبيد أدوم وإخوتهم ثمانية وستين, وعوبيد أدوم بن يديثون وحوسة بوابين.","16:39":"وصادوق الكاهن وإخوته الكهنة أمام مسكن الرب في المرتفعة التي في جبعون","16:40":"ليصعدوا محرقات للرب على مذبح المحرقة دائما صباحا ومساء, وحسب كل ما هو مكتوب في شريعة الرب التي أمر بها إسرائيل.","16:41":"ومعهم هيمان ويدوثون وباقي المنتخبين الذين ذكرت أسماؤهم ليحمدوا الرب, لأن إلى الأبد رحمته.","16:42":"ومعهم هيمان ويدوثون بأبواق وصنوج للمصوتين, وآلات غناء لله, وبنو يدوثون بوابون.","16:43":"ثم انطلق كل الشعب كل واحد إلى بيته, ورجع داود ليبارك بيته.","17:1":"وكان لما سكن داود في بيته, قال داود لناثان النبي: «هأنذا ساكن في بيت من أرز, وتابوت عهد الرب تحت شقق!»","17:2":"فقال ناثان لداود: «افعل كل ما في قلبك لأن الله معك».","17:3":"وفي تلك الليلة كان كلام الله إلى ناثان قائلا:","17:4":"«اذهب وقل لداود عبدي: هكذا قال الرب: أنت لا تبني لي بيتا للسكنى,","17:5":"لأني لم أسكن في بيت منذ يوم أصعدت إسرائيل إلى هذا اليوم, بل سرت من خيمة إلى خيمة, ومن مسكن إلى مسكن.","17:6":"في كل ما سرت مع جميع إسرائيل, هل تكلمت بكلمة مع أحد قضاة إسرائيل الذين أمرتهم أن يرعوا شعبي إسرائيل قائلا: لماذا لم تبنوا لي بيتا من أرز؟","17:7":"والآن فهكذا تقول لعبدي داود: هكذا قال رب الجنود: أنا أخذتك من المربض, من وراء الغنم لتكون رئيسا على شعبي إسرائيل,","17:8":"وكنت معك حيثما توجهت, وقرضت جميع أعدائك من أمامك, وعملت لك اسما كاسم العظماء الذين في الأرض.","17:9":"وعينت مكانا لشعبي إسرائيل وغرسته فسكن في مكانه, ولا يضطرب بعد, ولا يعود بنو الإثم يبلونه كما في الأول,","17:10":"ومنذ الأيام التي فيها أقمت قضاة على شعبي إسرائيل. وأذللت جميع أعدائك. وأخبرك أن الرب يبني لك بيتا.","17:11":"ويكون متى كملت أيامك لتذهب مع آبائك, أني أقيم بعدك نسلك الذي يكون من بنيك وأثبت مملكته.","17:12":"هو يبني لي بيتا وأنا أثبت كرسيه إلى الأبد.","17:13":"أنا أكون له أبا وهو يكون لي ابنا, ولا أنزع رحمتي عنه كما نزعتها عن الذي كان قبلك.","17:14":"وأقيمه في بيتي وملكوتي إلى الأبد, ويكون كرسيه ثابتا إلى الأبد».","17:15":"فحسب جميع هذا الكلام وحسب كل هذه الرؤيا كذلك كلم ناثان داود.","17:16":"فدخل الملك داود وجلس أمام الرب وقال: «من أنا أيها الرب الإله, وماذا بيتي حتى أوصلتني إلى هنا؟","17:17":"وقل هذا في عينيك يا الله فتكلمت عن بيت عبدك إلى زمان طويل, ونظرت إلي من العلاء كعادة الإنسان أيها الرب الإله.","17:18":"فماذا يزيد داود بعد لك لأجل إكرام عبدك وأنت قد عرفت عبدك؟","17:19":"يا رب, من أجل عبدك وحسب قلبك قد فعلت كل هذه العظائم, لتظهر جميع العظائم","17:20":"يا رب, ليس مثلك ولا إله غيرك حسب كل ما سمعناه بآذاننا.","17:21":"وأية أمة على الأرض مثل شعبك إسرائيل الذي سار الله ليفتديه لنفسه شعبا, لتجعل لك اسم عظائم ومخاوف بطردك أمما من أمام شعبك الذي افتديته من مصر.","17:22":"وقد جعلت شعبك إسرائيل لنفسك شعبا إلى الأبد, وأنت أيها الرب صرت لهم إلها.","17:23":"والآن أيها الرب, ليثبت إلى الأبد الكلام الذي تكلمت به عن عبدك وعن بيته وافعل كما نطقت.","17:24":"وليثبت ويتعظم اسمك إلى الأبد, فيقال: رب الجنود إله إسرائيل. هو الله لإسرائيل وليثبت بيت داود عبدك أمامك.","17:25":"لأنك يا إلهي قد أعلنت لعبدك أنك تبني له بيتا, لذلك وجد عبدك أن يصلي أمامك.","17:26":"والآن أيها الرب, أنت هو الله, وقد وعدت عبدك بهذا الخير.","17:27":"والآن قد ارتضيت بأن تبارك بيت عبدك ليكون إلى الأبد أمامك, لأنك أنت يا رب قد باركت وهو مبارك إلى الأبد».","18:1":"وبعد ذلك ضرب داود الفلسطينيين وذللهم, وأخذ جت وقراها من يد الفلسطينيين.","18:2":"وضرب موآب, فصار الموآبيون عبيدا لداود يقدمون هدايا.","18:3":"وضرب داود هدر عزر ملك صوبة في حماة حين ذهب ليقيم سلطته عند نهر الفرات,","18:4":"وأخذ داود منه ألف مركبة وسبعة آلاف فارس وعشرين ألف راجل, وعرقب داود كل خيل المركبات وأبقى منها مئة مركبة.","18:5":"فجاء أرام دمشق لنجدة هدر عزر ملك صوبة, فضرب داود من أرام اثنين وعشرين ألف رجل.","18:6":"وجعل داود محافظين في أرام دمشق, وصار الأراميون لداود عبيدا يقدمون هدايا. وكان الرب يخلص داود حيثما توجه.","18:7":"وأخذ داود أتراس الذهب التي كانت على عبيد هدر عزر وأتى بها إلى أورشليم.","18:8":"ومن طبحة وخون مدينتي هدر عزر أخذ داود نحاسا كثيرا جدا صنع منه سليمان بحر النحاس والأعمدة وآنية النحاس.","18:9":"وسمع توعو ملك حماة أن داود قد ضرب كل جيش هدد عزر ملك صوبة,","18:10":"فأرسل هدورام ابنه إلى الملك داود ليسأل عن سلامته ويباركه, لأنه حارب هدر عزر وضربه. لأن هدد عزر كانت له حروب مع توعو. وبيده جميع آنية الذهب والفضة والنحاس.","18:11":"هذه أيضا قدسها الملك داود للرب مع الفضة والذهب الذي أخذه من كل الأمم: من أدوم ومن موآب ومن بني عمون ومن الفلسطينيين ومن عماليق.","18:12":"وأبشاي ابن صروية ضرب من أدوم في وادي الملح ثمانية عشر ألفا.","18:13":"وجعل في أدوم محافظين, فصار جميع الأدوميين عبيدا لداود. وكان الرب يخلص داود حيثما توجه.","18:14":"وملك داود على جميع إسرائيل, وكان يجري قضاء وعدلا لكل شعبه.","18:15":"وكان يوآب ابن صروية على الجيش, ويهوشافاط بن أخيلود مسجلا,","18:16":"وصادوق بن أخيطوب وأبيمالك بن أبياثار كاهنين, وشوشا كاتبا,","18:17":"وبنايا بن يهوياداع على الجلادين والسعاة, وبنو داود الأولين بين يدي الملك.","19:1":"وكان بعد ذلك أن ناحاش ملك بني عمون مات, فملك ابنه عوضا عنه.","19:2":"فقال داود: «أصنع معروفا مع حانون بن ناحاش, لأن أباه صنع معي معروفا». فأرسل داود رسلا ليعزيه بأبيه. فجاء عبيد داود إلى أرض بني عمون إلى حانون ليعزوه.","19:3":"فقال رؤساء بني عمون لحانون: «هل يكرم داود أباك في عينيك حتى أرسل إليك معزين؟ أليس إنما لأجل الفحص والقلب وتجسس الأرض جاء عبيده إليك؟»","19:4":"فأخذ حانون عبيد داود وحلق لحاهم وقص ثيابهم من الوسط عند السوءة ثم أطلقهم.","19:5":"فذهب أناس وأخبروا داود عن الرجال. فأرسل للقائهم لأن الرجال كانوا خجلين جدا. وقال الملك: «أقيموا في أريحا حتى تنبت لحاكم ثم ارجعوا».","19:6":"ولما رأى بنو عمون أنهم قد أنتنوا عند داود, أرسل حانون وبنو عمون ألف وزنة من الفضة ليستأجروا لأنفسهم من أرام النهرين ومن أرام معكة ومن صوبة مركبات وفرسانا.","19:7":"فاستأجروا لأنفسهم اثنين وثلاثين ألف مركبة, وملك معكة وشعبه. فجاءوا ونزلوا مقابل ميدبا. واجتمع بنو عمون من مدنهم وأتوا للحرب.","19:8":"ولما سمع داود أرسل يوآب وكل جيش الجبابرة.","19:9":"فخرج بنو عمون واصطفوا للحرب عند باب المدينة, والملوك الذين جاءوا كانوا وحدهم في الحقل.","19:10":"ولما رأى يوآب أن مقدمة الحرب كانت نحوه من قدام ومن وراء, اختار من جميع منتخبي إسرائيل وصفهم للقاء أرام.","19:11":"وسلم بقية الشعب ليد أبشاي أخيه, فاصطفوا للقاء بني عمون.","19:12":"وقال: «إن قوي أرام علي تكون لي نجدة, وإن قوي بنو عمون عليك أنجدتك.","19:13":"تجلد, ولنتشدد لأجل شعبنا ولأجل مدن إلهنا, وما يحسن في عيني الرب يفعل».","19:14":"وتقدم يوآب والشعب الذين معه نحو أرام للمحاربة, فهربوا من أمامه.","19:15":"ولما رأى بنو عمون أنه قد هرب أرام هربوا هم أيضا من أمام أبشاي أخيه ودخلوا إلى المدينة. وجاء يوآب إلى أورشليم.","19:16":"ولما رأى أرام أنهم قد انكسروا أمام إسرائيل أرسلوا رسلا, وأبرزوا أرام الذين في عبر النهر, وأمامهم شوبك رئيس جيش هدر عزر.","19:17":"ولما أخبر داود جمع كل إسرائيل وعبر الأردن وجاء إليهم واصطف ضدهم. اصطف داود للقاء أرام في الحرب فحاربوه.","19:18":"وهرب أرام من أمام إسرائيل, وقتل داود من أرام سبعة آلاف مركبة وأربعين ألف راجل, وقتل شوبك رئيس الجيش.","19:19":"ولما رأى عبيد هدر عزر أنهم قد انكسروا أمام إسرائيل صالحوا داود وخدموه. ولم يشأ أرام أن ينجدوا بني عمون بعد.","20:1":"وكان عند تمام السنة في وقت خروج الملوك, اقتاد يوآب قوة الجيش وأخرب أرض بني عمون وأتى وحاصر ربة. وكان داود مقيما في أورشليم. فضرب يوآب ربة وهدمها.","20:2":"وأخذ داود تاج ملكهم عن رأسه, فوجد وزنه وزنة من الذهب, وفيه حجر كريم. فكان على رأس داود. وأخرج غنيمة المدينة وكانت كثيرة جدا.","20:3":"وأخرج الشعب الذين بها ونشرهم بمناشير ونوارج حديد وفؤوس. وهكذا صنع داود لكل مدن بني عمون. ثم رجع داود وكل الشعب إلى أورشليم.","20:4":"ثم بعد ذلك قامت حرب في جازر مع الفلسطينيين. حينئذ سبكاي الحوشي قتل سفاي من أولاد رافا فذلوا.","20:5":"وكانت أيضا حرب مع الفلسطينيين, فقتل ألحانان بن ياعور لحمي أخا جليات الجتي. وكانت قناة رمحه كنول النساجين.","20:6":"ثم كانت أيضا حرب في جت, وكان رجل طويل القامة أعنش, أصابعه أربع وعشرون, وهو أيضا ولد لرافا.","20:7":"ولما عير إسرائيل ضربه يهوناثان بن شمعا أخي داود.","20:8":"هؤلاء ولدوا لرافا في جت وسقطوا بيد داود وبيد عبيده.","21:1":"ووقف الشيطان ضد إسرائيل, وأغوى داود ليحصي إسرائيل.","21:2":"فقال داود ليوآب ولرؤساء الشعب: «اذهبوا عدوا إسرائيل من بئر سبع إلى دان, وأتوا إلي فأعلم عددهم».","21:3":"فقال يوآب: «ليزد الرب على شعبه أمثالهم مئة ضعف. أليسوا جميعا يا سيدي الملك عبيدا لسيدي؟ لماذا يطلب هذا سيدي؟ لماذا يكون سبب إثم لإسرائيل؟»","21:4":"فاشتد كلام الملك على يوآب. فخرج يوآب وطاف في كل إسرائيل ثم جاء إلى أورشليم.","21:5":"فدفع يوآب جملة عدد الشعب إلى داود, فكان كل إسرائيل ألف ألف ومئة ألف رجل مستلي السيف, ويهوذا أربع مئة وسبعين ألف رجل مستلي السيف,","21:6":"وأما لاوي وبنيامين فلم يعدهم معهم لأن كلام الملك كان مكروها لدى يوآب.","21:7":"وقبح في عيني الله هذا الأمر فضرب إسرائيل.","21:8":"فقال داود لله: «لقد أخطأت جدا حيث عملت هذا الأمر. والآن أزل إثم عبدك لأني سفهت جدا».","21:9":"فكلم الرب جاد رائي داود وقال:","21:10":"«اذهب وكلم داود قائلا: هكذا قال الرب: ثلاثة أنا عارض عليك فاختر لنفسك واحدا منها فأفعله بك».","21:11":"فجاء جاد إلى داود وقال له: «هكذا قال الرب: اقبل لنفسك:","21:12":"إما ثلاث سنين جوع, أو ثلاثة أشهر هلاك أمام مضايقيك وسيف أعدائك يدركك, أو ثلاثة أيام يكون فيها سيف الرب ووبأ في الأرض, وملاك الرب يعثو في كل تخوم إسرائيل. فانظر الآن ماذا أرد جوابا لمرسلي».","21:13":"فقال داود لجاد: «قد ضاق بي الأمر جدا. دعني أسقط في يد الرب لأن مراحمه كثيرة, ولا أسقط في يد إنسان».","21:14":"فجعل الرب وبأ في إسرائيل, فسقط من إسرائيل سبعون ألف رجل.","21:15":"وأرسل الله ملاكا على أورشليم لإهلاكها, وفيما هو يهلك رأى الرب فندم على الشر, وقال للملاك المهلك: «كفى الآن, رد يدك». وكان ملاك الرب واقفا عند بيدر أرنان اليبوسي.","21:16":"ورفع داود عينيه فرأى ملاك الرب واقفا بين الأرض والسماء, وسيفه مسلول بيده وممدود على أورشليم. فسقط داود والشيوخ على وجوههم مكتسين بالمسوح.","21:17":"وقال داود لله: «ألست أنا هو الذي أمر بإحصاء الشعب؟ وأنا هو الذي أخطأ وأساء, وأما هؤلاء الخراف فماذا عملوا؟ فأيها الرب إلهي لتكن يدك علي وعلى بيت أبي لا على شعبك لضربهم».","21:18":"فكلم ملاك الرب جاد أن يقول لداود أن يصعد داود ليقيم مذبحا للرب في بيدر أرنان اليبوسي.","21:19":"فصعد داود حسب كلام جاد الذي تكلم به باسم الرب.","21:20":"فالتفت أرنان فرأى الملاك. وبنوه الأربعة معه اختبأوا, وكان أرنان يدرس حنطة.","21:21":"وجاء داود إلى أرنان. وتطلع أرنان فرأى داود, وخرج من البيدر وسجد لداود على وجهه إلى الأرض.","21:22":"فقال داود لأرنان: «أعطني مكان البيدر فأبني فيه مذبحا للرب. بفضة كاملة أعطني إياه, فتكف الضربة عن الشعب».","21:23":"فقال أرنان لداود: «خذه لنفسك, وليفعل سيدي الملك ما يحسن في عينيه. انظر. قد أعطيت البقر للمحرقة, والنوارج للوقود, والحنطة للتقدمة. الجميع أعطيت».","21:24":"فقال الملك داود لأرنان: «لا! بل شراء أشتريه بفضة كاملة, لأني لا آخذ ما لك للرب فأصعد محرقة مجانية».","21:25":"ودفع داود لأرنان عن المكان ذهبا وزنه ست مئة شاقل.","21:26":"وبنى داود هناك مذبحا للرب, وأصعد محرقات وذبائح سلامة, ودعا الرب فأجابه بنار من السماء على مذبح المحرقة.","21:27":"وأمر الرب الملاك فرد سيفه إلى غمده.","21:28":"في ذلك الوقت لما رأى داود أن الرب قد أجابه في بيدر أرنان اليبوسي ذبح هناك.","21:29":"ومسكن الرب الذي عمله موسى في البرية ومذبح المحرقة كانا في ذلك الوقت في المرتفعة في جبعون.","21:30":"ولم يستطع داود أن يذهب إلى أمامه ليسأل الله لأنه خاف من جهة سيف ملاك الرب.","22:1":"فقال داود: «هذا هو بيت الرب الإله, وهذا هو مذبح المحرقة لإسرائيل».","22:2":"وأمر داود بجمع الأجنبيين الذين في أرض إسرائيل, وأقام نحاتين لنحت حجارة مربعة لبناء بيت الله.","22:3":"وهيأ داود حديدا كثيرا للمسامير لمصاريع الأبواب وللوصل, ونحاسا كثيرا بلا وزن,","22:4":"وخشب أرز لم يكن له عدد لأن الصيدونيين والصوريين أتوا بخشب أرز كثير إلى داود.","22:5":"وقال داود: «إن سليمان ابني صغير وغض, والبيت الذي يبنى للرب يكون عظيما جدا في الاسم والمجد في جميع الأراضي, فأنا أهيئ له». فهيأ داود كثيرا قبل وفاته.","22:6":"ودعا سليمان ابنه وأوصاه أن يبني بيتا للرب إله إسرائيل.","22:7":"وقال داود لسليمان: «يا ابني, قد كان في قلبي أن أبني بيتا لاسم الرب إلهي.","22:8":"فكان إلي كلام الرب قائلا: قد سفكت دما كثيرا وعملت حروبا عظيمة, فلا تبني بيتا لاسمي لأنك سفكت دماء كثيرة على الأرض أمامي.","22:9":"هوذا يولد لك ابن يكون صاحب راحة, وأريحه من جميع أعدائه حواليه, لأن اسمه يكون سليمان. فأجعل سلاما وسكينة في إسرائيل في أيامه.","22:10":"هو يبني بيتا لاسمي, وهو يكون لي ابنا, وأنا له أبا وأثبت كرسي ملكه على إسرائيل إلى الأبد.","22:11":"الآن يا ابني, ليكن الرب معك فتفلح وتبني بيت الرب إلهك كما تكلم عنك.","22:12":"إنما يعطيك الرب فطنة وفهما ويوصيك بإسرائيل لحفظ شريعة الرب إلهك.","22:13":"حينئذ تفلح إذا تحفظت لعمل الفرائض والأحكام التي أمر بها الرب موسى لأجل إسرائيل. تشدد وتشجع لا تخف ولا ترتعب.","22:14":"هأنذا في مذلتي هيأت لبيت الرب ذهبا مئة ألف وزنة, وفضة ألف ألف وزنة, ونحاسا وحديدا بلا وزن لأنه كثير. وقد هيأت خشبا وحجارة فتزيد عليها.","22:15":"وعندك كثيرون من عاملي الشغل: نحاتين وبنائين ونجارين وكل حكيم في كل عمل.","22:16":"الذهب والفضة والنحاس والحديد ليس لها عدد. قم واعمل, وليكن الرب معك».","22:17":"وأمر داود جميع رؤساء إسرائيل أن يساعدوا سليمان ابنه:","22:18":"«أليس الرب إلهكم معكم, وقد أراحكم من كل ناحية, لأنه دفع ليدي سكان الأرض فخضعت الأرض أمام الرب وأمام شعبه؟","22:19":"فالآن اجعلوا قلوبكم وأنفسكم لطلب الرب إلهكم, وقوموا وابنوا مقدس الرب الإله, ليؤتى بتابوت عهد الرب وبآنية قدس الله إلى البيت الذي يبنى لاسم الرب».","23:1":"ولما شاخ داود وشبع أياما ملك سليمان ابنه على إسرائيل.","23:2":"وجمع كل رؤساء إسرائيل والكهنة واللاويين,","23:3":"فعد اللاويون من ابن ثلاثين سنة فما فوق, فكان عددهم حسب رؤوسهم من الرجال ثمانية وثلاثين ألفا.","23:4":"من هؤلاء للمناظرة على عمل بيت الرب أربعة وعشرون ألفا. وستة آلاف عرفاء وقضاة.","23:5":"وأربعة آلاف بوابون, وأربعة آلاف مسبحون للرب بالآلات التي عملت للتسبيح.","23:6":"وقسمهم داود فرقا لبني لاوي: لجرشون وقهات ومراري.","23:7":"من الجرشونيين: لعدان وشمعي.","23:8":"بنو لعدان: الرأس يحيئيل ثم زيثام ويوئيل, ثلاثة.","23:9":"بنو شمعي: شلوميث وحزيئيل وهاران, ثلاثة. هؤلاء رؤوس آباء للعدان.","23:10":"وبنو شمعي: يحث وزينا ويعوش وبريعة. هؤلاء بنو شمعي أربعة.","23:11":"وكان يحث الرأس وزيزة الثاني. أما يعوش وبريعة فلم يكثرا الأولاد, فكانوا في الإحصاء لبيت أب واحد.","23:12":"بنو قهات: عمرام ويصهار وحبرون وعزيئيل, أربعة.","23:13":"ابنا عمرام: هارون وموسى, وأفرز هارون لتقديسه قدس أقداس هو وبنوه إلى الأبد, ليوقد أمام الرب ويخدمه ويبارك باسمه إلى الأبد.","23:14":"وأما موسى رجل الله فدعي بنوه مع سبط لاوي.","23:15":"ابنا موسى: جرشوم وأليعزر.","23:16":"بنو جرشوم: شبوئيل الرأس.","23:17":"وكان ابن أليعزر: رحبيا الرأس, ولم يكن لأليعزر بنون آخرون. وأما بنو رحبيا فكانوا كثيرين جدا.","23:18":"بنو يصهار: شلوميث الرأس.","23:19":"بنو حبرون: يريا الرأس وأمريا الثاني ويحزيئيل الثالث ويقمعام الرابع.","23:20":"ابنا عزيئيل: ميخا الرأس ويشيا الثاني.","23:21":"ابنا مراري: محلي وموشي. ابنا محلي: ألعازار وقيس.","23:22":"ومات ألعازار ولم يكن له بنون بل بنات, فأخذهن بنو قيس إخوتهن.","23:23":"بنو موشي: محلي وعادر ويريموث, ثلاثة.","23:24":"هؤلاء بنو لاوي حسب بيوت آبائهم رؤوس الآباء حسب إحصائهم في عدد الأسماء حسب رؤوسهم عاملو العمل لخدمة بيت الرب, من ابن عشرين سنة فما فوق.","23:25":"لأن داود قال: «قد أراح الرب إله إسرائيل شعبه فسكن في أورشليم إلى الأبد.","23:26":"وليس للاويين بعد أن يحملوا المسكن وكل آنيته لخدمته».","23:27":"لأنه حسب كلام داود الأخير عد بنو لاوي من ابن عشرين سنة فما فوق.","23:28":"لأنهم كانوا يقفون بين يدي بني هارون على خدمة بيت الرب في الدور والمخادع, وعلى تطهير كل قدس وعمل خدمة بيت الله,","23:29":"وعلى خبز الوجوه ودقيق التقدمة ورقاق الفطير وما يعمل على الصاج والمربوكات وعلى كل كيل وقياس,","23:30":"ولأجل الوقوف كل صباح لحمد الرب وتسبيحه وكذلك في المساء,","23:31":"ولكل إصعاد محرقات للرب في السبوت والأهلة والمواسم بالعدد حسب المرسوم عليهم دائما أمام الرب,","23:32":"وليحرسوا حراسة خيمة الاجتماع, وحراسة القدس, وحراسة بني هارون إخوتهم في خدمة بيت الرب.","24:1":"وهذه فرق بني هارون: بنو هارون: ناداب وأبيهو, ألعازار وإيثامار.","24:2":"ومات ناداب وأبيهو قبل أبيهما ولم يكن لهما بنون, فكهن ألعازار وإيثامار.","24:3":"وقسمهم داود وصادوق من بني ألعازار, وأخيمالك من بني إيثامار, حسب وكالتهم في خدمتهم.","24:4":"ووجد لبني ألعازار رؤوس رجال أكثر من بني إيثامار, فانقسموا لبني ألعازار رؤوسا لبيت آبائهم ستة عشر, ولبني إيثامار لبيت آبائهم ثمانية.","24:5":"وانقسموا بالقرعة, هؤلاء مع هؤلاء, لأن رؤساء القدس ورؤساء بيت الله كانوا من بني ألعازار ومن بني إيثامار.","24:6":"وكتبهم شمعيا بن نثنئيل الكاتب من اللاويين أمام الملك والرؤساء وصادوق الكاهن وأخيمالك بن أبياثار ورؤوس الآباء للكهنة واللاويين. فأخذ بيت أب واحد لألعازار, وأخذ واحد لإيثامار.","24:7":"فخرجت القرعة الأولى ليهوياريب. الثانية ليدعيا.","24:8":"الثالثة لحاريم. الرابعة لسعوريم.","24:9":"الخامسة لملكيا. السادسة لميامين.","24:10":"السابعة لهقوص. الثامنة لأبيا.","24:11":"التاسعة ليشوع. العاشرة لشكنيا.","24:12":"الحادية عشرة لألياشيب. الثانية عشرة لياقيم.","24:13":"الثالثة عشرة لحفة. الرابعة عشرة ليشبآب.","24:14":"الخامسة عشرة لبلجة. السادسة عشرة لإيمير.","24:15":"السابعة عشرة لحيزير. الثامنة عشرة لهفصيص.","24:16":"التاسعة عشرة لفقحيا. العشرون ليحزقيئيل.","24:17":"الحادية والعشرون لياكين. الثانية والعشرون لجامول.","24:18":"الثالثة والعشرون لدلايا. الرابعة والعشرون لمعزيا.","24:19":"فهذه وكالتهم وخدمتهم للدخول إلى بيت الرب حسب حكمهم عن يد هارون أبيهم كما أمره الرب إله إسرائيل.","24:20":"وأما بنو لاوي الباقون: فمن بني عمرام: شوبائيل, ومن بني شوبائيل: يحديا.","24:21":"وأما رحبيا, فمن بني رحبيا: الرأس يشيا.","24:22":"ومن اليصهاريين: شلوموث, ومن بني شلوموث: يحث.","24:23":"ومن بني حبرون: يريا وأمريا الثاني ويحزيئيل الثالث ويقمعام الرابع.","24:24":"من بني عزيئيل: ميخا. من بني ميخا: شامور.","24:25":"أخو ميخا: يشيا, ومن بني يشيا: زكريا.","24:26":"ابنا مراري: محلي وموشي. ابن يعزيا بنو.","24:27":"من بني مراري ليعزيا: بنو وشوهم وزكور وعبري.","24:28":"من محلي: ألعازار ولم يكن له بنون.","24:29":"وأما قيس, فابن قيس يرحمئيل.","24:30":"وبنو موشي: محلي وعادر ويريموث. هؤلاء بنو اللاويين حسب بيوت آبائهم.","24:31":"وألقوا هم أيضا قرعا مقابل إخوتهم بني هارون أمام داود الملك وصادوق وأخيمالك ورؤوس آباء الكهنة واللاويين. الآباء الرؤوس كما إخوتهم الأصاغر.","25:1":"وأفرز داود ورؤساء الجيش للخدمة بني آساف وهيمان ويدوثون المتنبئين بالعيدان والرباب والصنوج. وكان عددهم من رجال العمل حسب خدمتهم.","25:2":"من بني آساف: زكور ويوسف ونثنيا وأشرئيلة. بنو آساف تحت يد آساف المتنبئ بين يدي الملك.","25:3":"من يدوثون, بنو يدوثون: جدليا وصري ويشعيا وحشبيا ومتثيا, ستة. تحت يد أبيهم يدوثون المتنبئ بالعود لأجل الحمد والتسبيح للرب.","25:4":"من هيمان: بقيا ومتنيا وعزيئيل وشبوئيل ويريموث وحننيا وحناني وإيليآثة وجدلتي وروممتي عزر ويشبقاشة وملوثي وهوثير ومحزيوث.","25:5":"جميع هؤلاء بنو هيمان رائي الملك بكلام الله لرفع القرن. ورزق الرب هيمان أربعة عشر ابنا وثلاث بنات.","25:6":"كل هؤلاء تحت يد أبيهم لأجل غناء بيت الرب بالصنوج والرباب والعيدان لخدمة بيت الله, تحت يد الملك وآساف ويدوثون وهيمان.","25:7":"وكان عددهم مع إخوتهم المتعلمين الغناء للرب, كل الخبيرين مئتين وثمانية وثمانين.","25:8":"وألقوا قرع الحراسة الصغير كما الكبير, المعلم مع التلميذ.","25:9":"فخرجت القرعة الأولى التي هي لآساف ليوسف. الثانية لجدليا, هو وإخوته وبنوه اثنا عشر.","25:10":"الثالثة لزكور, بنوه وإخوته اثنا عشر.","25:11":"الرابعة ليصري, بنوه وإخوته اثنا عشر.","25:12":"الخامسة لنثنيا, بنوه وإخوته اثنا عشر.","25:13":"السادسة لبقيا, بنوه وإخوته اثنا عشر.","25:14":"السابعة ليشرئيلة, بنوه وإخوته اثنا عشر.","25:15":"الثامنة ليشعيا, بنوه وإخوته اثنا عشر.","25:16":"التاسعة لمتنيا, بنوه وإخوته اثنا عشر.","25:17":"العاشرة لشمعي, بنوه وإخوته اثنا عشر.","25:18":"الحادية عشرة لعزرئيل, بنوه وإخوته اثنا عشر.","25:19":"والثانية عشرة لحشبيا, بنوه وإخوته اثنا عشر.","25:20":"الثالثة عشرة لشوبائيل, بنوه وإخوته اثنا عشر.","25:21":"الرابعة عشرة لمتثيا, بنوه وإخوته اثنا عشر.","25:22":"الخامسة عشرة ليريموث, بنوه وإخوته اثنا عشر.","25:23":"السادسة عشرة لحننيا, بنوه وإخوته اثنا عشر.","25:24":"السابعة عشرة ليشبقاشة, بنوه وإخوته اثنا عشر.","25:25":"الثامنة عشرة لحناني, بنوه وإخوته اثنا عشر.","25:26":"التاسعة عشرة لملوثي, بنوه وإخوته اثنا عشر.","25:27":"العشرون لإيليآثة, بنوه وإخوته اثنا عشر.","25:28":"الحادية والعشرون لهوثير, بنوه وإخوته اثنا عشر.","25:29":"الثانية والعشرون لجدلتي, بنوه وإخوته اثنا عشر,","25:30":"الثالثة والعشرون لمحزيوث, بنوه وإخوته اثنا عشر.","25:31":"الرابعة والعشرون لروممتي عزر, بنوه وإخوته اثنا عشر.","26:1":"وأما أقسام البوابين فمن القورحيين: مشلميا بن قوري من بني آساف.","26:2":"وكان لمشلميا بنون: زكريا البكر, ويديعئيل الثاني, وزبديا الثالث, ويثنئيل الرابع,","26:3":"وعيلام الخامس, ويهوحانان السادس, وأليهو عيناي السابع.","26:4":"وكان لعوبيد أدوم بنون: شمعيا البكر, ويهوزاباد الثاني, ويوآخ الثالث, وساكار الرابع, ونثنئيل الخامس,","26:5":"وعميئيل السادس, ويساكر السابع, وفعلتاي الثامن. لأن الله باركه.","26:6":"ولشمعيا ابنه ولد بنون تسلطوا في بيت آبائهم لأنهم جبابرة بأس.","26:7":"بنو شمعيا: عثني ورفائيل وعوبيد وألزاباد إخوته أصحاب بأس. أليهو وسمكيا.","26:8":"كل هؤلاء من بني عوبيد أدوم هم وبنوهم وإخوتهم أصحاب بأس بقوة في الخدمة, اثنان وستون لعوبيد أدوم.","26:9":"وكان لمشلميا بنون وإخوة أصحاب بأس ثمانية عشر.","26:10":"وكان لحوسة من بني مراري بنون: شمري الرأس, مع أنه لم يكن بكرا جعله أبوه رأسا,","26:11":"حلقيا الثاني, وطبليا الثالث, وزكريا الرابع. كل بني حوسة وإخوته ثلاثة عشر.","26:12":"لفرق البوابين هؤلاء حسب رؤوس الجبابرة حراسة كما لإخوتهم للخدمة في بيت الرب.","26:13":"وألقوا قرعا الصغير كالكبير حسب بيوت آبائهم لكل باب.","26:14":"فأصابت القرعة من جهة الشرق شلميا. ولزكريا ابنه المشير بفطنة ألقوا قرعا, فخرجت القرعة له إلى الشمال.","26:15":"لعوبيد أدوم إلى الجنوب ولبنيه المخازن.","26:16":"لشفيم وحوسة إلى الغرب مع باب شلكة في مصعد الدرج محرس مقابل محرس.","26:17":"من جهة الشرق كان اللاويون ستة. من جهة الشمال أربعة لليوم. من جهة الجنوب أربعة لليوم. ومن جهة المخازن اثنين اثنين.","26:18":"من جهة الرواق إلى الغرب أربعة في المصعد واثنين في الرواق.","26:19":"هذه أقسام البوابين من بني القورحيين ومن بني مراري.","26:20":"وأما اللاويون فأخيا على خزائن بيت الله وعلى خزائن الأقداس.","26:21":"وأما بنو لعدان, فبنو لعدان الجرشوني رؤوس بيت الآباء للعدان, الجرشوني يحيئيلي.","26:22":"بنو يحيئيلي: زيثام ويوئيل أخوه على خزائن بيت الرب.","26:23":"من العمراميين واليصهاريين والحبرونيين والعزيئيليين,","26:24":"كان شبوئيل بن جرشوم بن موسى وكان رئيسا على الخزائن.","26:25":"وإخوته من أليعزر: رحبيا ابنه, ويشعيا ابنه, ويورام ابنه, وزكري ابنه, وشلوميث ابنه.","26:26":"شلوميث هذا وإخوته كانوا على جميع خزائن الأقداس التي قدسها داود الملك ورؤوس الآباء ورؤساء الألوف والمئات ورؤساء الجيش.","26:27":"من الحروب ومن الغنائم قدسوا لتشديد بيت الرب.","26:28":"وكل ما قدسه صموئيل الرائي وشاول بن قيس وأبنير بن نير ويوآب ابن صروية, كل مقدس كان تحت يد شلوميث وإخوته.","26:29":"ومن اليصهاريين: كننيا وبنوه للعمل الخارجي على إسرائيل عرفاء وقضاة.","26:30":"من الحبرونيين: حشبيا وإخوته ذوو بأس ألف وسبع مئة موكلين على إسرائيل في عبر الأردن غربا في كل عمل الرب وفي خدمة الملك.","26:31":"من الحبرونيين: يريا رأس الحبرونيين حسب مواليد آبائه. في السنة الرابعة لملك داود طلبوا فوجد فيهم جبابرة بأس في يعزير جلعاد.","26:32":"وإخوته ذوو بأس ألفان وسبع مئة رؤوس آباء. ووكلهم داود الملك على الرأوبينيين والجاديين ونصف سبط منسى في كل أمور الله وأمور الملك.","27:1":"وبنو إسرائيل حسب عددهم من رؤوس الآباء ورؤساء الألوف والمئات وعرفاؤهم الذين يخدمون الملك في كل أمور الفرق الداخلين والخارجين شهرا فشهرا لكل شهور السنة, كل فرقة كانت أربعة وعشرين ألفا.","27:2":"على الفرقة الأولى للشهر الأول يشبعام بن زبديئيل, وفي فرقته أربعة وعشرون ألفا.","27:3":"من بني فارص كان رأس جميع رؤساء الجيوش للشهر الأول.","27:4":"وعلى فرقة الشهر الثاني دوداي الأخوخي, ومن فرقته مقلوث الرئيس. وفي فرقته أربعة وعشرون ألفا.","27:5":"رئيس الجيش الثالث للشهر الثالث بنايا بن يهوياداع الكاهن الرأس, وفي فرقته أربعة وعشرون ألفا.","27:6":"هو بنايا جبار الثلاثين, وعلى الثلاثين ومن فرقته عميزاباد ابنه.","27:7":"الرابع للشهر الرابع عسائيل أخو يوآب وزبديا ابنه بعده, وفي فرقته أربعة وعشرون ألفا.","27:8":"الخامس للشهر الخامس الرئيس شمحوث اليزراحي, وفي فرقته أربعة وعشرون ألفا.","27:9":"السادس للشهر السادس عيرا بن عقيش التقوعي, وفي فرقته أربعة وعشرون ألفا.","27:10":"السابع للشهر السابع حالص الفلوني من بني أفرايم, وفي فرقته أربعة وعشرون ألفا.","27:11":"الثامن للشهر الثامن سبكاي الحوشاتي من الزارحيين, وفي فرقته أربعة وعشرون ألفا.","27:12":"التاسع للشهر التاسع أبيعزر العناثوثي من بنيامين, وفي فرقته أربعة وعشرون ألفا.","27:13":"العاشر للشهر العاشر مهراي النطوفاتي من الزارحيين, وفي فرقته أربعة وعشرون ألفا.","27:14":"الحادي عشر للشهر الحادي عشر بنايا الفرعتوني من بني أفرايم, وفي فرقته أربعة وعشرون ألفا.","27:15":"الثاني عشر للشهر الثاني عشر خلداي النطوفاتي من عثنئيل, وفي فرقته أربعة وعشرون ألفا.","27:16":"وعلى أسباط إسرائيل: للرأوبينيين الرئيس: أليعزر بن زكري. للشمعونيين: شفطيا بن معكة.","27:17":"للاويين: حشبيا بن قموئيل. لهارون: صادوق.","27:18":"ليهوذا: أليهو من إخوة داود. ليساكر: عمري بن ميخائيل.","27:19":"لزبولون: يشمعيا بن عوبديا. لنفتالي: يريموث بن عزرئيل.","27:20":"لبني أفرايم: هوشع بن عززيا. لنصف سبط منسى: يوئيل بن فدايا.","27:21":"لنصف سبط منسى في جلعاد: يدو بن زكريا. لبنيامين: يعسيئيل بن أبنير.","27:22":"لدان: عزرئيل بن يروحام. هؤلاء رؤساء أسباط إسرائيل.","27:23":"ولم يأخذ داود عددهم من ابن عشرين سنة فما دون, لأن الرب قال إنه يكثر إسرائيل كنجوم السماء.","27:24":"يوآب ابن صروية ابتدأ يحصي ولم يكمل لأنه كان جرى ذلك سخط على إسرائيل, ولم يدون العدد في سفر أخبار الأيام للملك داود.","27:25":"وعلى خزائن الملك عزموت بن عديئيل. وعلى الخزائن في الحقل في المدن والقرى والحصون يهوناثان بن عزيا.","27:26":"وعلى الفعلة في الحقل لشغل الأرض عزري بن كلوب.","27:27":"وعلى الكروم شمعي الرامي. وعلى ما في الكروم من خزائن الخمر زبدي الشفمي.","27:28":"وعلى الزيتون والجميز اللذين في السهل بعل حانان الجديري. وعلى خزائن الزيت يوعاش.","27:29":"وعلى البقر السائم في شارون شطراي الشاروني. وعلى البقر الذي في الأودية شافاط بن عدلاي.","27:30":"وعلى الجمال أوبيل الإسماعيلي. وعلى الحمير يحديا الميرونوثي.","27:31":"وعلى الغنم يازيز الهاجري. كل هؤلاء رؤساء الأملاك التي للملك داود.","27:32":"ويهوناثان عم داود كان مشيرا ورجلا مختبرا وفقيها. ويحيئيل بن حكموني كان مع بني الملك.","27:33":"وكان أخيتوفل مشيرا للملك, وحوشاي الأركي صاحب الملك.","27:34":"وبعد أخيتوفل يهوياداع بن بنايا وأبياثار. وكان رئيس جيش الملك يوآب.","28:1":"وجمع داود كل رؤساء إسرائيل, رؤساء الأسباط ورؤساء الفرق الخادمين الملك, ورؤساء الألوف ورؤساء المئات, ورؤساء كل الأموال والأملاك التي للملك ولبنيه, مع الخصيان والأبطال وكل جبابرة البأس, إلى أورشليم.","28:2":"ووقف داود الملك على رجليه وقال: «اسمعوني يا إخوتي وشعبي. كان في قلبي أن أبني بيت قرار لتابوت عهد الرب ولموطئ قدمي إلهنا, وقد هيأت للبناء.","28:3":"ولكن الله قال لي: لا تبني بيتا لاسمي لأنك أنت رجل حروب وقد سفكت دما.","28:4":"وقد اختارني الرب إله إسرائيل من كل بيت أبي لأكون ملكا على إسرائيل إلى الأبد, لأنه إنما اختار يهوذا رئيسا, ومن بيت يهوذا بيت أبي, ومن بني أبي سر بي ليملكني على كل إسرائيل.","28:5":"ومن كل بني, لأن الرب أعطاني بنين كثيرين, إنما اختار سليمان ابني ليجلس على كرسي مملكة الرب على إسرائيل.","28:6":"وقال لي: إن سليمان ابنك هو يبني بيتي ودياري, لأني اخترته لي ابنا, وأنا أكون له أبا,","28:7":"وأثبت مملكته إلى الأبد إذا تشدد للعمل حسب وصاياي وأحكامي كهذا اليوم.","28:8":"والآن في أعين كل إسرائيل محفل الرب, وفي سماع إلهنا, احفظوا واطلبوا جميع وصايا الرب إلهكم لكي ترثوا الأرض الجيدة وتورثوها لأولادكم بعدكم إلى الأبد.","28:9":"وأنت يا سليمان ابني, اعرف إله أبيك واعبده بقلب كامل ونفس راغبة, لأن الرب يفحص جميع القلوب, ويفهم كل تصورات الأفكار. فإذا طلبته يوجد منك, وإذا تركته يرفضك إلى الأبد.","28:10":"انظر الآن لأن الرب قد اختارك لتبني بيتا للمقدس, فتشدد واعمل».","28:11":"وأعطى داود سليمان ابنه مثال الرواق وبيوته وخزائنه وعلاليه ومخادعه الداخلية وبيت الغطاء,","28:12":"ومثال كل ما كان عنده بالروح لديار بيت الرب ولجميع المخادع حواليه, ولخزائن بيت الله وخزائن الأقداس,","28:13":"ولفرق الكهنة واللاويين, ولكل عمل خدمة بيت الرب, ولكل آنية خدمة بيت الرب.","28:14":"فمن الذهب بالوزن لما هو من ذهب, لكل آنية خدمة فخدمة, ولجميع آنية الفضة فضة بالوزن, لكل آنية خدمة فخدمة.","28:15":"وبالوزن لمنائر الذهب وسرجها من ذهب بالوزن لكل منارة فمنارة وسرجها, ولمنائر الفضة بالوزن لكل منارة وسرجها حسب خدمة منارة فمنارة.","28:16":"وذهبا بالوزن لموائد خبز الوجوه لكل مائدة فمائدة, وفضة لموائد الفضة.","28:17":"وذهبا خالصا للمناشل والمناضح والكؤوس. ولأقداح الذهب بالوزن لقدح فقدح, ولأقداح الفضة بالوزن لقدح فقدح.","28:18":"ولمذبح البخور ذهبا مصفى بالوزن, وذهبا لمثال مركبة الكروبيم الباسطة أجنحتها المظللة تابوت عهد الرب.","28:19":"«قد أفهمني الرب كل ذلك بالكتابة بيده علي, أي كل أشغال المثال».","28:20":"وقال داود لسليمان ابنه: «تشدد وتشجع واعمل. لا تخف ولا ترتعب, لأن الرب الإله إلهي معك. لا يخذلك ولا يتركك حتى تكمل كل عمل خدمة بيت الرب.","28:21":"وهوذا فرق الكهنة واللاويين لكل خدمة, بيت الله. ومعك في كل عمل كل نبيه بحكمة لكل خدمة, والرؤساء وكل الشعب تحت كل أوامرك».","29:1":"وقال داود الملك لكل المجمع: «إن سليمان ابني الذي وحده اختاره الله, إنما هو صغير وغض, والعمل عظيم لأن الهيكل ليس لإنسان بل للرب الإله.","29:2":"وأنا بكل قوتي هيأت لبيت إلهي: الذهب لما هو من ذهب, والفضة لما هو من فضة, والنحاس لما هو من نحاس, والحديد لما هو من حديد, والخشب لما هو من خشب, وحجارة الجزع, وحجارة للترصيع, وحجارة كحلاء ورقماء, وكل حجارة كريمة, وحجارة الرخام بكثرة.","29:3":"وأيضا لأني قد سررت ببيت إلهي, لي خاصة من ذهب وفضة قد دفعتها لبيت إلهي فوق جميع ما هيأته لبيت القدس:","29:4":"ثلاثة آلاف وزنة ذهب من ذهب أوفير, وسبعة آلاف وزنة فضة مصفاة, لأجل تغشية حيطان البيوت.","29:5":"الذهب للذهب, والفضة للفضة ولكل عمل بيد أرباب الصنائع. فمن ينتدب اليوم لملء يده للرب؟»","29:6":"فانتدب رؤساء الآباء ورؤساء أسباط إسرائيل ورؤساء الألوف والمئات ورؤساء أشغال الملك,","29:7":"وأعطوا لخدمة بيت الله خمسة آلاف وزنة وعشرة آلاف درهم من الذهب, وعشرة آلاف وزنة من الفضة, وثمانية عشر ألف وزنة من النحاس, ومئة ألف وزنة من الحديد.","29:8":"ومن وجد عنده حجارة أعطاها لخزينة بيت الرب عن يد يحيئيل الجرشوني.","29:9":"وفرح الشعب بانتدابهم, لأنهم بقلب كامل انتدبوا للرب. وداود الملك أيضا فرح فرحا عظيما.","29:10":"وبارك داود الرب أمام كل الجماعة, وقال داود: «مبارك أنت أيها الرب إله إسرائيل أبينا من الأزل وإلى الأبد.","29:11":"لك يا رب العظمة والجبروت والجلال والبهاء والمجد, لأن لك كل ما في السماء والأرض. لك يا رب الملك, وقد ارتفعت رأسا على الجميع.","29:12":"والغنى والكرامة من لدنك, وأنت تتسلط على الجميع, وبيدك القوة والجبروت, وبيدك تعظيم وتشديد الجميع.","29:13":"والآن, يا إلهنا نحمدك ونسبح اسمك الجليل.","29:14":"ولكن من أنا, ومن هو شعبي حتى نستطيع أن ننتدب هكذا؟ لأن منك الجميع ومن يدك أعطيناك.","29:15":"لأننا نحن غرباء أمامك, ونزلاء مثل كل آبائنا. أيامنا كالظل على الأرض وليس رجاء.","29:16":"أيها الرب إلهنا, كل هذه الثروة التي هيأناها لنبني لك بيتا لاسم قدسك, إنما هي من يدك, ولك الكل.","29:17":"وقد علمت يا إلهي أنك أنت تمتحن القلوب وتسر بالاستقامة. أنا باستقامة قلبي انتدبت بكل هذه, والآن شعبك الموجود هنا رأيته بفرح ينتدب لك.","29:18":"يا رب إله إبراهيم وإسحاق وإسرائيل آبائنا, احفظ هذه إلى الأبد في تصور أفكار قلوب شعبك, وأعد قلوبهم نحوك.","29:19":"وأما سليمان ابني فأعطه قلبا كاملا ليحفظ وصاياك, شهاداتك وفرائضك, وليعمل الجميع, وليبني الهيكل الذي هيأت له».","29:20":"ثم قال داود لكل الجماعة: «باركوا الرب إلهكم». فبارك كل الجماعة الرب إله آبائهم, وخروا وسجدوا للرب وللملك.","29:21":"وذبحوا للرب ذبائح وأصعدوا محرقات للرب في غد ذلك اليوم: ألف ثور وألف كبش وألف خروف مع سكائبها, وذبائح كثيرة لكل إسرائيل.","29:22":"وأكلوا وشربوا أمام الرب في ذلك اليوم بفرح عظيم. وملكوا ثانية سليمان بن داود, ومسحوه للرب رئيسا, وصادوق كاهنا.","29:23":"وجلس سليمان على كرسي الرب ملكا مكان داود أبيه, ونجح وأطاعه كل إسرائيل.","29:24":"وجميع الرؤساء والأبطال وجميع أولاد الملك داود أيضا خضعوا لسليمان الملك.","29:25":"وعظم الرب سليمان جدا في أعين جميع إسرائيل, وجعل عليه جلالا ملكيا لم يكن على ملك قبله في إسرائيل.","29:26":"وداود بن يسى ملك على كل إسرائيل.","29:27":"والزمان الذي ملك فيه على إسرائيل أربعون سنة. ملك سبع سنين في حبرون, وملك ثلاثا وثلاثين سنة في أورشليم.","29:28":"ومات بشيبة صالحة وقد شبع أياما وغنى وكرامة. وملك سليمان ابنه مكانه.","29:29":"وأمور داود الملك الأولى والأخيرة هي مكتوبة في سفر أخبار صموئيل الرائي, وأخبار ناثان النبي, وأخبار جاد الرائي,","29:30":"مع كل ملكه وجبروته والأوقات التي عبرت عليه وعلى إسرائيل وعلى كل ممالك الأروض."};
